window.DOCS_SEARCH = [{"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "", "a": "", "x": "Khái niệm DQN không học policy trực tiếp. Nó học hàm Q(s, a) : \"đứng ở trạng thái s, làm action a, về sau kỳ vọng thu được bao nhiêu\". Policy chỉ là chọn action có Q lớn nhất. Đây là bản DQN gốc (replay buffer và target network), không kèm các cải tiến như Double hay Dueling."}, {"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "Ý tưởng một đoạn", "a": "idea", "x": "Agent chơi, mỗi bước cất lại (s, a, r, s', done) vào replay buffer . Việc học rút ngẫu nhiên một minibatch từ buffer và kéo Q(s, a) về gần mục tiêu Bellman : y = r + γ · (1 − done) · max_a' Q_target(s', a') loss = Huber( Q(s, a) − y ) Q_target là bản sao \"đóng băng\" của mạng, chỉ cập nhật định kỳ (mỗi target_update bước env) để mục tiêu không chạy theo chính nó mỗi bước. DQN là off-policy : dữ liệu cũ vẫn dùng được, nên mỗi mẫu được tái sử dụng nhiều lần."}, {"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "Một vòng lặp", "a": "loop", "x": "Mỗi vòng for it in range(1, n_iters + 1) (với n_iters = total_steps // n_envs ) tương ứng n_envs bước env: Thu thập : với mỗi nhóm env, nhận kết quả bước trước, gửi đi action mới theo epsilon-greedy. Chuyển tiếp hoàn chỉnh của cả 16 env được ghi vào buffer một lượt. Học (khi step ≥ learning_starts ): lặp updates_per_iter lần: rút batch_size mẫu, tính y , tính loss Huber, backward , cắt gradient về max_grad , step . Phần này chạy lúc emulator đang chạy bước kế tiếp. Việc định kỳ : sao chép trọng số sang target network khi step ≥ next_target ; ghi log mỗi log_every ; lưu checkpoint mỗi save_ever"}, {"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "Khám phá: epsilon-greedy", "a": "epsilon", "x": "Với xác suất ε agent chọn action ngẫu nhiên , ngược lại chọn argmax Q . ε giảm tuyến tính trong một phần đầu của run: eps_steps = int(eps_frac × total_steps) eps(step) = max(eps_end, eps_start − (eps_start − eps_end) × step / eps_steps) Mặc định: từ 1.0 xuống 0.05 trong 0.05 × 10,000,000 = 500,000 bước đầu, rồi giữ 0.05 đến hết. Lưu ý ε được quyết định riêng cho từng env mỗi bước (mỗi env tung xúc xắc độc lập) nhưng cùng một giá trị ε cho tất cả."}, {"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "Replay buffer tiết kiệm bộ nhớ", "a": "buffer", "x": "Lưu đủ (s, s') với mỗi quan sát 4×84×84 thì tốn gấp 8 lần. VecFrameReplayBuffer chỉ cất frame mới nhất của mỗi bước ( 84×84 byte) và dựng lại chồng 4 frame lúc rút mẫu. Mỗi env là một \"cột\" riêng trong bộ đệm, nên chồng 4 frame không bao giờ trộn frame của hai env khác nhau. Cột nhớ thời điểm bắt đầu episode ( ep_start ). Đầu episode thì frame đầu được lặp lại để đủ 4 frame, giống hệt FrameStack . Trạng thái kế tiếp s' chính là chồng frame tại bước P+1 , nên không cần lưu riêng. Dung lượng: khoảng buffer_size × 7,080 byte (84×84 ảnh + action, reward, done, mốc episode). 200,000 mẫu ≈ 1.4 GB RA"}, {"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "Tỷ lệ tái sử dụng (replay ratio)", "a": "ratio", "x": "Mỗi vòng thu n_envs = 16 mẫu mới và học updates_per_iter × batch_size = 1 × 128 mẫu. Mỗi mẫu trung bình được học lại 128 / 16 = 8 lần. Đó đúng bằng DQN gốc (minibatch 32 mỗi 4 bước: 32 / 4 = 8 ). Công thức tổng quát: replay_ratio = updates_per_iter × batch_size / n_envs Đổi n_envs mà không đổi batch_size hay updates_per_iter sẽ đổi tỷ lệ này, và đổi luôn cân bằng giữa \"thu dữ liệu\" và \"học\". Xem Chọn và chỉnh tham số ."}, {"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "Con số của cấu hình mặc định", "a": "numbers", "x": "Đại lượng Công thức Giá trị Số vòng lặp total_steps // n_envs 625,000 Bước đầu chỉ thu, chưa học learning_starts 20,000 (1,250 vòng) Buffer đầy sau buffer_size bước 200,000 (12,500 vòng) Epsilon về mức thấp nhất sau eps_frac × total_steps 500,000 bước Số lần cập nhật target total_steps / target_update ≈ 1,000 Số điểm trong log total_steps / log_every 100"}, {"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "Những gì bản DQN này không có", "a": "omitted", "x": "Double DQN : mục tiêu dùng max của target network (dễ ước lượng Q quá cao). Thêm Double DQN chỉ cần sửa hai dòng, xem hướng dẫn . Không Dueling, không Prioritized Replay, không n-step return, không Noisy Nets. Không cắt reward về -1/0/+1; thay vào đó dùng biến đổi log1p(r/10) ( chi tiết )."}, {"p": "concepts/dqn.html", "t": "DQN trong pacman_rl", "h": "Khi chơi/đánh giá", "a": "eval", "x": "Chính sách chơi của DQN là epsilon-greedy với ε nhỏ (mặc định 0.05 , chỉnh bằng --eps hay dqn_policy(model, device, eps=...) ). Greedy tuyệt đối ( eps=0 ) có thể khiến agent kẹt lặp lại một chuyển động, nên giữ một chút ngẫu nhiên."}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "", "a": "", "x": "Khái niệm Agent không nhìn thấy game như bạn. Nó nhận 4 ảnh xám 84x84 chồng lên nhau, chọn một trong 9 hướng, và được \"thưởng\" bằng một con số đã biến đổi. Trang này giải thích từng lớp xử lý đó, và vì sao có tới ba loại \"điểm\" khác nhau trong thư viện."}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "Thuật ngữ dùng xuyên suốt", "a": "glossary", "x": "Thuật ngữ Nghĩa trong pacman_rl Frame Một khung hình của emulator Atari. Bước (step) Một lần agent chọn action. Action được giữ nguyên 4 frame (frame-skip 4), nên 1 bước = 4 frame . Mọi tham số có đuôi _steps hay \"bước env\" đều tính theo đơn vị này. Mạng (life) Ms. Pacman có 3 mạng. Mất một mạng thì Pacman hồi sinh và game tiếp tục. Ván (game) Từ lúc bắt đầu đến khi hết cả 3 mạng. Điểm một ván là tổng điểm trong 3 mạng. Episode (khi học) Một mạng. Khi train, mất mạng được báo là \"kết thúc episode\" ( done=True ), dù game chưa hết. Xem EpisodicLife . Rollout (PPO) Đoạn dữ liệu thu được từ tất cả"}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "Từ game tới ma trận số", "a": "pipeline", "x": "make_env() trong envs/factory.py dựng pipeline tiền xử lý tiêu chuẩn của DeepMind cho Atari: Lớp Tác dụng Thiết lập gym.make(\"ALE/MsPacman-v5\") Emulator gốc frameskip=1 (để wrapper tự skip), repeat_action_probability=0.0 (không có \"sticky action\", env thuần xác định), full_action_space=False (chỉ 9 action cần thiết) AtariPreprocessing Xử lý ảnh và nhịp frame_skip=4 , screen_size=84 , grayscale_obs=True ( False khi rgb_scale ), noop_max=30 , scale_obs=False (giữ uint8 0..255), terminal_on_life_loss=False EpisodicLife Chỉ khi học ( episodic_life=True ) Mất mạng = done . Xem bên dưới. FrameStack("}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "9 action", "a": "actions", "x": "Không gian action là Discrete(9) (hằng số N_ACTIONS ), theo thứ tự chỉ số 0 đến 8: 0 1 2 3 4 5 6 7 8 NOOP UP RIGHT LEFT DOWN UPRIGHT UPLEFT DOWNRIGHT DOWNLEFT Vì có 9 action nên policy ngẫu nhiên hoàn toàn có entropy bằng ln 9 ≈ 2.197 . Con số này là mốc để đọc đường entropy của PPO."}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "EpisodicLife: cho cái chết một cái giá", "a": "episodic-life", "x": "Nếu chỉ báo \"hết episode\" khi hết cả 3 mạng, agent khó học rằng mất mạng là tệ: mất mạng thứ nhất chỉ khiến game tiếp tục như thường. EpisodicLife ( envs/wrappers.py ) xử lý bằng cách: Khi số mạng giảm mà game chưa hết, báo terminated=True . Thuật toán coi đó là kết thúc episode: PPO cắt giá trị tương lai ( nonterm = 0 ), DQN không bootstrap ( 1 - done = 0 ). Khi vector env tự reset sau done , wrapper không reset game thật nếu game chưa hết. Nó chỉ bước thêm 1 action NOOP để đi tiếp từ chỗ hồi sinh. Game thật chỉ reset khi hết cả 3 mạng. Lúc đó wrapper ghi điểm cả ván vào info[\"game_score\"] . "}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "Ba loại điểm, đừng lẫn", "a": "scores", "x": "Đây là chỗ dễ nhầm nhất khi đọc log. Cùng một sự kiện \"ăn viên năng lượng\" xuất hiện dưới ba dạng khác nhau tùy mục đích: Loại Giá trị ví dụ Lấy ở đâu Dùng để Reward thật 0, 10, 50, 200 ... reward trả về từ PipelinedEnvs.recv Đếm sự kiện ( count_events ). Không dùng để học. Reward học 0, 0.69, 1.79, 3.04 ... cfg.reward_fn(reward) - step_pen - death_pen * died (mặc định log_reward , hai mức phạt bằng 0; với PPO lấy từ step_penalty / death_penalty hoặc penalty_schedule ) Tính gradient. Đây là thứ agent thực sự \"nhìn thấy\". Điểm cả ván vài trăm đến vài nghìn info[\"game_score\"] → danh sách episode"}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "Vì sao reward học là log1p(r / 10)", "a": "log-reward", "x": "Điểm thật nhảy từ 10 (chấm nhỏ) tới 1600 (ma thứ tư), chênh nhau 160 lần. Gradient tỉ lệ với reward nên các sự kiện lớn sẽ lấn át mọi thứ. Hàm log_reward nén thang đó mà vẫn giữ thứ tự: sự kiện nào đáng giá hơn thì reward lớn hơn. Sự kiện Reward thật Reward học = log1p(r/10) Không có gì 0 0.00 Ăn chấm nhỏ 10 0.69 Ăn viên năng lượng 50 1.79 Ăn ma lần 1 / 2 / 3 / 4 200 / 400 / 800 / 1600 3.04 / 3.71 / 4.39 / 5.08 Khác với cách \"cắt reward về dấu\" (clip về -1/0/+1) của DQN gốc: ở đây vẫn phân biệt được chấm, viên năng lượng và ma."}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "Đếm viên năng lượng và ma", "a": "count-events", "x": "count_events(reward) đếm theo reward thật của một bước: bằng đúng 50 thì tính một viên năng lượng, thuộc (200, 400, 800, 1600) thì tính một con ma. Hai chỉ số cộng dồn này đi vào log[\"pellets\"] và log[\"ghosts\"] . Đây là phép đếm gần đúng: Nếu hai sự kiện rơi vào cùng 4 frame của một bước thì reward là tổng và bị bỏ sót. Trái cây 200 điểm (từ màn 2 trở đi) có thể bị tính nhầm là ma. Sai số nhỏ. Hãy dùng hai chỉ số này để xem xu hướng (agent có ngày càng biết ăn ma sau viên năng lượng không), không phải để kiểm toán chính xác."}, {"p": "concepts/environment.html", "t": "Môi trường và các loại điểm", "h": "Hằng số của gói pacman_rl.envs", "a": "constants", "x": "Tên Giá trị Ý nghĩa ENV_ID \"ALE/MsPacman-v5\" Id env gymnasium N_ACTIONS 9 Số action (minimal action set) OBS_SHAPE (4, 84, 84) Hình dạng quan sát PELLET_REWARD 50 Reward thật của viên năng lượng GHOST_REWARDS (200, 400, 800, 1600) Reward thật khi ăn ma liên tiếp"}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "", "a": "", "x": "Khái niệm Khi train, pacman_rl chạy 16 game cùng lúc. Đó không phải 16 agent hay 16 policy khác nhau: chỉ có một mạng neural, còn 16 game là 16 \"con mắt\" để thu dữ liệu nhanh hơn và đa dạng hơn."}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "Một policy, nhiều env", "a": "one-policy", "x": "Mỗi bước thời gian, mạng nhận quan sát của tất cả env, trả về action cho từng env. Dữ liệu từ mọi env được gộp lại để cập nhật cùng một bộ trọng số. env 0 (process) env 1 (process) env 2 (process) ⋮ env 15 (process) MỘT mạng một bộ trọng số một optimizer Cập nhật batch gộp từ cả 16 env quan sát (4×84×84) → action dữ liệu trọng số mới (quay lại mạng) Các env không có policy riêng. Sau mỗi lần cập nhật, cả 16 env dùng trọng số mới. Cái khác nhau giữa các env chỉ là chúng đang ở trạng thái game nào : mỗi env có seed riêng ( seed + chỉ số env ) và đi những ván khác nhau. Đó là điều ta muốn. Không "}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "Vì sao dùng nhiều env", "a": "why", "x": ""}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "1. Tốc độ", "a": "why-speed", "x": "Phần chậm nhất của RL trên Atari là chạy emulator, không phải tính toán trên GPU. Mỗi env là một process riêng ( AsyncVectorEnv ) nên 16 emulator chạy trên nhiều nhân CPU cùng lúc. GPU thì xử lý một nhóm quan sát trong một lần forward thay vì từng cái một."}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "2. Dữ liệu ít tương quan hơn (lợi ích về thuật toán)", "a": "why-stability", "x": "Một env chạy liên tục cho ra các mẫu liền kề rất giống nhau (cùng khung cảnh, cùng đoạn đường). Gradient tính trên dữ liệu như vậy thiên lệch. Ở 16 env, một lát cắt thời gian chứa 16 tình huống độc lập, nên batch đa dạng hơn và việc học PPO ổn định hơn. Với DQN, mỗi vòng cũng thêm 16 chuyển tiếp từ 16 tình huống khác nhau vào replay buffer."}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "Pipeline: CPU và GPU không chờ nhau", "a": "pipeline", "x": "16 env được chia thành 2 nhóm, mỗi nhóm 8 env . Mỗi nhóm là một AsyncVectorEnv riêng (8 process con). Hai nhóm chạy so le: trong lúc GPU chọn action cho nhóm này thì emulator của nhóm kia đang chạy. Emulator nhóm 0 CPU, 8 process Emulator nhóm 1 CPU, 8 process GPU model.act(...) chạy 8 env chạy 8 env chạy 8 env chạy 8 env chạy 8 env chạy 8 env g0 g1 g0 g1 g0 g1 g0 … thời gian → (ô xanh lục: GPU chọn action cho một nhóm; ô xanh dương: emulator chạy 1 bước) Hình minh họa tỷ lệ thời gian chứ không phải số đo thật: emulator thường chậm hơn nhiều so với một lần forward của mạng. Trong code PPO, mẫu"}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "Số env ảnh hưởng thế nào tới thuật toán", "a": "effects", "x": "PPO DQN Một \"đơn vị công việc\" 1 update = n_envs × n_steps mẫu (mặc định 2,048) 1 vòng lặp = n_envs chuyển tiếp mới (mặc định 16) Tăng n_envs Batch to hơn (nếu giữ n_steps ), ít update hơn trên cùng total_steps , mẫu đa dạng hơn Replay buffer đầy nhanh hơn; mỗi vòng thu nhiều mẫu hơn nên tỷ lệ tái sử dụng giảm trừ khi tăng batch_size hoặc updates_per_iter Ràng buộc n_envs chẵn (chia 2 nhóm); nên để n_envs × n_steps chia hết cho n_minibatches n_envs chẵn; buffer_size nên chia hết cho n_envs Vì vậy n_envs không chỉ là nút \"chạy nhanh/chậm\": đổi nó là đổi kích thước batch của PPO. Nếu bạn giảm n_"}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "Seed của từng env", "a": "seeds", "x": "PipelinedEnvs.reset(seed) reset nhóm g với seed + g × (n_envs / 2) . Bên trong, AsyncVectorEnv.reset(seed=s) gán seed s + i cho env thứ i của nhóm. Kết quả: env có chỉ số toàn cục k nhận seed seed + k , mọi env đều khác nhau mà chạy lại với cùng seed thì khởi tạo y hệt. Cùng seed chưa chắc cho cùng đường học Seed cố định chỉ làm các env xuất phát giống nhau. Thứ tự các process nhả kết quả, tính không xác định của GPU và việc lấy mẫu action khiến hai lần chạy cùng seed vẫn lệch nhau. Muốn kết luận về độ tốt của một cấu hình, hãy chạy nhiều seed, đừng chỉ tin một lần."}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "Chế độ render", "a": "render", "x": "Với render=True ( --render trên CLI), PipelinedEnvs đổi sang SyncVectorEnv : toàn bộ env chạy tuần tự trong một process, và chỉ env số 0 mở cửa sổ game. Pipeline vẫn còn nhưng không còn song song thật, nên tốc độ giảm mạnh. Chỉ dùng để quan sát, đừng dùng để train thật. Nếu chỉ muốn thỉnh thoảng xem agent chơi mà không làm chậm train, dùng watch_every ( --watch-every N ): cứ mỗi N bước env, training dừng lại để mở một cửa sổ riêng cho agent chơi, rồi tiếp tục."}, {"p": "concepts/parallel-envs.html", "t": "Env song song và pipeline", "h": "Chi phí tài nguyên", "a": "cost", "x": "Tài nguyên Tiêu tốn Process n_envs process con, cộng process chính. Mỗi process con chỉ import pacman_rl.envs (không có torch) nên nhẹ. RAM, PPO Rollout nằm trên thiết bị tính toán: n_steps × n_envs × 4 × 84 × 84 byte ≈ 58 MB với cấu hình mặc định. RAM, DQN Replay buffer ≈ buffer_size × 7,080 byte (≈ 1.4 GB cho 200,000 mẫu), nằm trong RAM hệ thống. CPU Tận dụng nhiều nhân. Nhiều process hơn số nhân thật sẽ tranh nhau và không nhanh thêm."}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "", "a": "", "x": "Khái niệm PPO (Proximal Policy Optimization) học trực tiếp một policy: thu một mớ dữ liệu bằng policy hiện tại, rồi cập nhật policy sao cho không đi quá xa so với bản cũ. Trang này đi qua từng bước của train_ppo và chỉ ra mỗi tham số của PPOConfig nằm ở đâu trong công thức."}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "Ý tưởng một đoạn", "a": "idea", "x": "Policy gradient thuần dễ bất ổn: một lần cập nhật hơi lớn có thể phá hỏng policy và dữ liệu sau đó toàn là rác. PPO giải quyết bằng cách đo tỷ lệ xác suất giữa policy mới và policy lúc thu dữ liệu, rồi cắt tỷ lệ đó trong khoảng [1 − ε, 1 + ε] ( ε = clip_eps ). Nhờ vậy ta được phép học nhiều epoch trên cùng một rollout mà không sợ policy nhảy quá xa. PPO là thuật toán on-policy : dữ liệu chỉ dùng cho vài lần cập nhật rồi bỏ đi, rollout kế tiếp thu bằng policy mới. Khác với DQN giữ dữ liệu cũ trong replay buffer."}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "Vòng lặp ba pha", "a": "loop", "x": "Mỗi vòng for update in range(n_updates) làm ba việc nối nhau: Pha 1 Thu rollout n_steps bước x n_envs env, bằng policy hiện tại Pha 2 Tính GAE ước lượng \"hành động này tốt hơn trung bình bao nhiêu\" (advantage) Pha 3 Cập nhật epochs lần quét rollout, mỗi lần chia n_minibatches phần"}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "Pha 1: thu rollout", "a": "phase1", "x": "Với mỗi bước t và mỗi nhóm env, code gọi model.act(obs) để lấy ba thứ rồi cất vào bộ đệm có hình (n_steps, n_envs, ...) : Bộ đệm Nội dung Dùng ở B_obs Quan sát (4,84,84) uint8 Tính lại xác suất ở pha 3 B_act Action đã chọn Pha 3 B_logp log π_old(a|s) lúc chọn Mẫu số của tỷ lệ ở pha 3 B_val V_old(s) do critic dự đoán GAE (pha 2) B_rew Reward học cfg.reward_fn(reward thật) GAE B_done 1 nếu bước đó mất mạng hoặc hết game GAE Sau n_steps bước mỗi env, ta có n_envs × n_steps mẫu (mặc định 16 × 128 = 2,048). Việc chia nhóm và chạy xen kẽ với GPU xem ở Env song song và pipeline ."}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "Pha 2: GAE", "a": "phase2", "x": "Ta cần advantage A_t : hành động tại t tốt hơn mức trung bình của trạng thái đó bao nhiêu. GAE (Generalized Advantage Estimation) tính nó lùi từ cuối rollout về đầu: δ_t = r_t + γ · V(s_{t+1}) · (1 − done_t) − V(s_t) A_t = δ_t + γ · λ · (1 − done_t) · A_{t+1} return_t = A_t + V(s_t) ← mục tiêu để huấn luyện critic Trong code ( γ = cfg.gamma , λ = cfg.lam ): for t in reversed(range(n_steps)): next_value = last_value if t == n_steps - 1 else B_val[t + 1] nonterm = 1.0 - B_done[t] delta = B_rew[t] + cfg.gamma * next_value * nonterm - B_val[t] gae = delta + cfg.gamma * cfg.lam * nonterm * gae adv["}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "Pha 3: cập nhật", "a": "phase3", "x": "Rollout được \"duỗi phẳng\" thành batch = n_envs × n_steps mẫu rồi lặp epochs lần: xáo trộn, chia n_minibatches phần, mỗi phần tính một lần gradient. ratio = π_new(a|s) / π_old(a|s) = exp(logp_new − logp_old) A = (A − mean(A)) / (std(A) + 1e-8) ← chuẩn hóa trong minibatch pg_loss = −mean( min( ratio · A , clip(ratio, 1−ε, 1+ε) · A ) ) v_loss = mean( (V_new(s) − return)² ) entropy = mean( H[π_new(·|s)] ) loss = pg_loss + c1 · v_loss − c2 · entropy Thành phần Vai trò Tham số pg_loss Đẩy xác suất của action tốt lên, action tệ xuống, nhưng bị cắt khi tỷ lệ đã ra ngoài [1−ε, 1+ε] theo hướng có lợi, đ"}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "Con số của cấu hình mặc định", "a": "numbers", "x": "Đại lượng Công thức Giá trị Batch (mẫu mỗi update) n_envs × n_steps 2,048 Minibatch batch // n_minibatches 512 Số update total_steps // batch 976 Số bước env thực sự chạy n_updates × batch 1,998,848 Lần tính gradient mỗi update epochs × n_minibatches 16 Tổng lần tính gradient 976 × 16 15,616"}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "Lịch giảm lr và các chi tiết triển khai", "a": "schedules", "x": "Learning rate giảm tuyến tính về 0 : ở update u , lr = cfg.lr × (1 − u / n_updates) . Đầu run học mạnh, cuối run tinh chỉnh nhẹ. Adam với eps=1e-5 (không phải 1e-8 mặc định của PyTorch), theo thiết lập chuẩn của PPO trên Atari. Khởi tạo trực giao : thân CNN dùng gain √2 ; lớp actor dùng gain 0.01 để policy ban đầu gần như đều (entropy ≈ ln 9); lớp critic dùng gain 1. Chọn action bằng Gumbel-max trong ActorCriticCNN.act : cộng nhiễu Gumbel vào logit rồi lấy argmax. Cùng phân phối với Categorical.sample() nhưng ít phép toán hơn nên nhanh hơn khi gọi từng bước nhỏ. Chỉ số log ( kl , clipfrac , v_"}, {"p": "concepts/ppo.html", "t": "PPO trong pacman_rl", "h": "Những gì bản PPO này không có", "a": "omitted", "x": "Để bạn không kỳ vọng nhầm, đây là các thành phần hay gặp ở các bản PPO khác nhưng không có trong train_ppo : Không chuẩn hóa reward theo độ lệch chuẩn chạy; thay vào đó dùng biến đổi log1p cố định. Không cắt value loss (không có \"value clipping\"). Không giảm dần clip_eps ; nó cố định cả run (chỉ lr giảm). Không dừng sớm epoch khi KL vượt ngưỡng; luôn chạy đủ epochs . Không có mạng hồi quy (LSTM); trí nhớ ngắn hạn đến từ việc chồng 4 frame. Muốn thêm một trong các thứ trên, xem Thêm thuật toán mới (hoặc thêm cờ vào PPOConfig như hướng dẫn ở đó)."}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "", "a": "", "x": "Đóng góp Hướng dẫn từng bước, kèm một ví dụ chạy được: A2C trong khoảng 130 dòng, dùng lại env song song và mạng sẵn có. Sau đó là cách thêm một biến thể nhỏ (Double DQN) chỉ bằng một cờ trong config. A2C ở đây là ví dụ, không có sẵn trong thư viện Mã A2C bên dưới đã được thử đầy đủ: train, eval và plot qua dòng lệnh đều chạy. Tuy nhiên siêu tham số chưa được tinh chỉnh cho Ms. Pacman, nên hãy coi nó là mẫu về cấu trúc , không phải bảo đảm về chất lượng học."}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Thuật toán mới hay chỉ một cờ?", "a": "decide", "x": "Thay đổi Nên làm Đổi một vài dòng của vòng lặp hiện có (Double DQN, thêm value clipping cho PPO...) Thêm trường vào Config, rẽ nhánh trong hàm train hiện có. Xem Double DQN . Vòng lặp khác hẳn (A2C, SAC rời rạc, Rainbow...) Tạo agents/<tên>.py riêng. Phần còn lại của trang này."}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Những chỗ phải chạm vào", "a": "touchpoints", "x": "File Việc cần làm Bắt buộc? agents/<tên>.py (mới) Dataclass config và hàm train_<tên> Có agents/__init__.py Import, thêm vào ALGOS và __all__ Có (để CLI thấy) models/__init__.py Thêm vào MODEL_CLASSES (để load_run nạp được) Có models/networks.py Mạng mới, nếu không dùng lại ActorCriticCNN / QNetwork Nếu cần cli.py Thêm tên vào các choices=[...] (có 2 chỗ) và sửa _policy Có (để chạy từ dòng lệnh) evaluation.py Hàm <tên>_policy nếu cách chọn action khác Nếu cần __init__.py (gói) Thêm tên vào _EXPORTS để from pacman_rl import ... hoạt động Tùy chọn tests/ , docs/html/ Test cho phần không cần emul"}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Hợp đồng của một hàm train", "a": "contract", "x": "Để mọi thứ khác (CLI, vẽ, đánh giá, lưu/nạp) dùng được thuật toán của bạn, hàm train cần tuân thủ: Chữ ký chuẩn : train_<tên>(cfg=None, *, model=None, save_path=None, device=None, render=False, watch_every=0, watch_episodes=1) . Siêu tham số vào cfg (dataclass); các tùy chọn chạy là keyword riêng, vì chúng không đổi kết quả học. Trả về TrainResult(model, log, episodes) . log : dict khóa → list, mọi list cùng độ dài với log[\"step\"] (bước env). Phải có step , pellets , ghosts để các hàm vẽ dùng được. episodes : list (bước env, điểm thật cả ván) , lấy từ giá trị scores (phần tử thứ tư; phần tử th"}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Ví dụ: thêm A2C", "a": "a2c", "x": ""}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Khác PPO ở đâu", "a": "a2c-idea", "x": "A2C đơn giản hơn PPO: rollout ngắn (mặc định 5 bước mỗi env), tính return n bước, một lần cập nhật trên rollout đó (không có epoch hay minibatch hay clip). Vì dùng lại ActorCriticCNN và cùng kiểu rollout như PPO, phần lớn mã là sao chép cấu trúc train_ppo rồi thay phần tính loss. loss = −mean( log π(a|s) · A ) + c1 · mean( (V(s) − R)² ) − c2 · mean( H[π] ) với R_t = r_t + γ · (1 − done_t) · R_{t+1}, A = R − V(s) (không truyền gradient qua A)"}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Bước 1. Tạo agents/a2c.py", "a": "a2c-file", "x": "\"\"\"A2C (advantage actor-critic đồng bộ) cho Ms. Pacman: rollout ngắn, một lần cập nhật cho mỗi rollout.\"\"\" import time from dataclasses import dataclass from typing import Callable import numpy as np import torch import torch.nn as nn import torch.optim as optim from ..envs import PipelinedEnvs, count_events, log_reward from ..evaluation import ppo_policy, watch from ..models import ActorCriticCNN from ..utils import get_device, set_seed from .common import TrainResult @dataclass class A2CConfig: total_steps: int = 2_000_000 n_envs: int = 16 n_steps: int = 5 # bước mỗi env trong một rollout (b"}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Những điểm đáng chú ý trong mã", "a": "a2c-notes", "x": "Dataclass config có reward_fn , log_every , save_every như hợp đồng. Giá trị mặc định (lr 7e-4, n_steps=5 , RMSprop) lấy theo thiết lập A2C thông dụng trên Atari. launch và vòng thu rollout y hệt PPO (nhưng không cần B_logp và B_val , vì A2C tính lại log-prob và value ngay lúc cập nhật). Return n bước nối vào model(obs)[1] , giá trị critic của quan sát cuối rollout. Chỉ một lần backward trên toàn rollout (batch n_envs × n_steps = 80 với mặc định). adv được detach() để gradient của policy không chảy vào critic qua advantage. Log có step , pellets , ghosts (bắt buộc) và thêm ent , v_loss , pg_lo"}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Bước 2. Đăng ký", "a": "a2c-register", "x": "agents/__init__.py : để CLI thấy thuật toán. from .a2c import A2CConfig, train_a2c # thêm dòng này cùng các import khác ALGOS = {\"ppo\": (PPOConfig, train_ppo), \"dqn\": (DQNConfig, train_dqn), \"a2c\": (A2CConfig, train_a2c)} __all__ = [\"A2CConfig\", \"train_a2c\", \"TrainResult\", ...] # giữ nguyên phần còn lại models/__init__.py : để load_run / load_model dựng lại đúng lớp mạng từ tên thuật toán. A2C dùng lại ActorCriticCNN : MODEL_CLASSES = {\"ppo\": ActorCriticCNN, \"dqn\": QNetwork, \"a2c\": ActorCriticCNN} cli.py : có hai chỗ choices=[\"ppo\", \"dqn\"] (lệnh train và vòng lặp tạo eval / play ); đổi cả hai "}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Bước 3. Chạy thử", "a": "a2c-run", "x": "python -m pacman_rl train a2c --steps 4000 --set log_every=20 --name a2c_try --out runs python -m pacman_rl eval a2c --name a2c_try --episodes 1 --greedy python -m pacman_rl plot a2c:a2c_try --out a2c.png Ba lệnh này đều đã chạy thành công với đúng các thay đổi ở trên. Dòng log đầu tiên có dạng: A2C: 50 updates x 80 mẫu = 4,000 bước, 16 env song song Run chỉ 4,000 bước nên dùng để kiểm tra pipeline, không để xem chất lượng học."}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Bước 4. Viết test (không cần emulator)", "a": "a2c-tests", "x": "Test các phần thuần như tính return hoặc hình dạng đầu ra. Gọn nhất là tách phần tính return thành hàm riêng có thể test; ví dụ kiểm tra mạng dùng chung và định dạng log: from pacman_rl.agents import ALGOS from pacman_rl.models import MODEL_CLASSES, ActorCriticCNN def test_a2c_registered(): cfg_cls, train = ALGOS[\"a2c\"] assert cfg_cls().n_steps == 5 and callable(train) assert MODEL_CLASSES[\"a2c\"] is ActorCriticCNN"}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Biến thể nhỏ: Double DQN bằng một cờ", "a": "double-dqn", "x": "Double DQN chỉ khác DQN gốc ở cách tính mục tiêu: chọn action bằng mạng chính, nhưng đánh giá giá trị bằng target network. Việc này chống ước lượng Q quá cao. Không cần file mới."}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Sửa agents/dqn.py", "a": "double-edit", "x": "Thêm trường vào DQNConfig (giữ mặc định False để hành vi cũ không đổi): max_grad: float = 10.0 double: bool = False # True: Double DQN (chọn action bằng mạng chính, đánh giá bằng target) Thay dòng tính mục tiêu y = r + cfg.gamma * (1 - d) * q_target(s2).max(1)[0] bằng: if cfg.double: a2 = q(s2).argmax(1, keepdim=True) next_q = q_target(s2).gather(1, a2).squeeze(1) else: next_q = q_target(s2).max(1)[0] y = r + cfg.gamma * (1 - d) * next_q Đoạn này nằm trong khối with torch.no_grad(): sẵn có."}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Chạy", "a": "double-run", "x": "python -m pacman_rl train dqn --set double=1 --name dqn_double_s0 --set ép kiểu theo kiểu của giá trị mặc định; với trường bool , dùng 1 hoặc 0 (không dùng true / false ). Cả hai chế độ ( double=1 và double=0 ) đã được chạy thử và cho ra log hợp lệ. Nhớ cập nhật tài liệu Thêm một khối tham số double vào DQNConfig (bảng tóm tắt, và một mục theo mẫu <section class=\"param\"> ) và bỏ dòng \"không phải Double DQN\" ở mục \"Những thứ cố định\" cùng trang DQN ."}, {"p": "contributing/add-algorithm.html", "t": "Thêm thuật toán mới", "h": "Danh sách kiểm tra trước khi gửi", "a": "checklist", "x": "Chạy ngắn bằng CLI thành công: train , eval , plot (và play nếu có màn hình). Log có step , pellets , ghosts , cùng độ dài; load_run nạp lại được run vừa lưu. Ctrl+C giữa chừng vẫn lưu được kết quả. Không import torch trong envs/ . Test mới trong tests/ pass: xem Quy ước, test, viết docs . Docs đã cập nhật: trang tham chiếu config, cột \"Một dòng\" trong bảng tóm tắt, và nav.js nếu thêm trang."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "", "a": "", "x": "Đóng góp Mã nguồn được chia theo trách nhiệm, các module phụ thuộc một chiều và không có vòng import. Trang này cho bạn bản đồ để biết sửa gì ở đâu, và lý do đằng sau các lựa chọn thiết kế."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Cấu trúc thư mục", "a": "layout", "x": "pacman_rl/ ├── pyproject.toml ├── README.md ├── docs/html/ tài liệu này ├── src/pacman_rl/ │ ├── envs/ tạo env, wrapper, env song song, reward (KHÔNG import torch) │ │ ├── factory.py make_env, ENV_ID, N_ACTIONS, OBS_SHAPE │ │ ├── wrappers.py EpisodicLife │ │ ├── vector.py PipelinedEnvs, pop_game_scores, pop_deaths │ │ └── rewards.py log_reward, count_events │ ├── models/ │ │ └── networks.py make_cnn, ActorCriticCNN, QNetwork │ ├── agents/ │ │ ├── ppo.py PPOConfig, train_ppo │ │ ├── dqn.py DQNConfig, train_dqn │ │ ├── buffers.py VecFrameReplayBuffer │ │ └── common.py TrainResult │ ├── evaluatio"}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Module phụ thuộc nhau thế nào", "a": "deps", "x": "Mũi tên A → B nghĩa là A import B. Không có vòng import. cli.py │ ┌────────────┼──────────────┬──────────────┐ ▼ ▼ ▼ ▼ plotting.py runs.py agents/ evaluation.py │ │ ┌────────┤ ppo.py ────────┤ │ │ │ │ dqn.py │ │ ▼ ▼ │ buffers.py │ │ models/ │ common.py │ │ │ ▼ ▼ └──────► utils.py ◄──── envs/ ◄────────────┘ (factory, wrappers, vector, rewards) KHÔNG import torch Module Trách nhiệm Nội dung chính envs/factory.py Tạo một env đã tiền xử lý make_env , ENV_ID , N_ACTIONS , OBS_SHAPE envs/wrappers.py Đổi tín hiệu kết thúc khi học EpisodicLife envs/vector.py Chạy nhiều env song song, xen kẽ với GPU Pi"}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Luồng dữ liệu khi train", "a": "flow", "x": "16 process con (AsyncVectorEnv), chia 2 nhóm x 8 ┌───────────────────────────────────────────────────────┐ │ gym.make(ALE/MsPacman-v5) │ │ → AtariPreprocessing (skip 4, xám, 84x84, noop 30) │ │ → EpisodicLife (mất mạng = done, ghi game_score, │ │ life_lost) │ │ → FrameStack(4) → obs uint8 (4,84,84) │ └───────────────┬───────────────────────▲───────────────┘ obs, reward thật, done, game_score, died │ action ▼ │ PipelinedEnvs.recv(g) PipelinedEnvs.send(g) │ ▲ ├─ count_events(reward thật) → log[\"pellets\"], log[\"ghosts\"] ├─ died → log[\"deaths\"] ├─ game_score → episodes [(bước, điểm thật)] └─ cfg.r"}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Nên đọc code theo thứ tự nào", "a": "reading-order", "x": "envs/factory.py → envs/wrappers.py : biết quan sát và tín hiệu \"kết thúc\" đến từ đâu. envs/vector.py : hiểu send / recv và vì sao có 2 nhóm. models/networks.py : ngắn, chỉ vài chục dòng. agents/ppo.py : ba pha rõ ràng (rollout, GAE, cập nhật). Đây là \"mẫu\" cho thuật toán on-policy. agents/dqn.py và agents/buffers.py : mẫu cho thuật toán off-policy. runs.py , evaluation.py , plotting.py , cli.py : phần xung quanh."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Lý do thiết kế và đánh đổi", "a": "decisions", "x": ""}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Config là dataclass, tham số chạy là keyword riêng", "a": "config-split", "x": "PPOConfig / DQNConfig chỉ chứa siêu tham số, tức những gì quyết định kết quả và nên ghi vào báo cáo. Các thứ như model , save_path , device , render , watch_every là tham số của train_* vì chúng không đổi kết quả. Đổi lại, gọi hàm dài hơn một chút: train_ppo(PPOConfig(total_steps=...)) thay vì train_ppo(total_steps) ."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "import pacman_rl không kéo torch", "a": "no-torch", "x": "__init__.py nạp lười (PEP 562 __getattr__ ). Mỗi process con của AsyncVectorEnv chỉ cần pacman_rl.envs , nên 16 process không phải nạp torch: khởi động nhanh hơn và đỡ hàng GB RAM. Vì vậy đừng import torch trong envs/ , và đừng để envs/ import từ module có torch ( agents , models , evaluation ...). PipelinedEnvs dùng functools.partial(make_env, ...) thay cho lambda để hàm tạo env pickle được theo tham chiếu."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "TrainResult là NamedTuple", "a": "train-result", "x": "Viết model, log, eps = train_ppo(...) (như notebook cũ) vẫn chạy, mà đọc result.episodes cũng rõ nghĩa."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Định dạng file lưu giữ như notebook", "a": "file-format", "x": "{name}.pt , {name}_episodes.npy , {name}_log.npy , nên nạp được kết quả đã train trước khi có thư viện. Nhược điểm: không lưu config và optimizer, nên chưa resume train chính xác được."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Ctrl+C không làm mất kết quả", "a": "interrupt", "x": "Vòng lặp bắt KeyboardInterrupt , đóng env, lưu .pt rồi trả về TrainResult của phần đã chạy."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Vòng train giữ sát bản notebook", "a": "loop-mirror", "x": "Mã train được tách từ notebooks/ms_pacman.ipynb gần như nguyên văn (chỉ đổi biến toàn cục thành cfg.* và device ). Muốn tối ưu thì đổi sau, khi đã có thư viện để so trước và sau."}, {"p": "contributing/architecture.html", "t": "Kiến trúc mã nguồn", "h": "Nên xem lại khi dự án lớn lên", "a": "future", "x": "Lưu config cùng run (ví dụ {name}_config.json ) để biết run nào dùng siêu tham số gì khi chạy nhiều cấu hình, nhiều seed. Checkpoint đầy đủ (model, optimizer, bước hiện tại, lịch lr, buffer) để train tiếp đúng chỗ sau khi máy treo. Hiện model= chỉ nạp trọng số. Reward có trạng thái chính xác (phạt \"đứng bí\" reset theo mất mạng): cần wrapper env hoặc recv trả thêm tín hiệu; xem Reward shaping . Logger chung (TensorBoard hoặc CSV) thay cho dict, nếu cần theo dõi run dài từ xa. Số nhóm n_groups hiện cố định là 2 trong các trainer; có thể đưa lên config."}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "", "a": "", "x": "Đóng góp Những quy ước giúp mã mới trông và hoạt động như mã sẵn có, cách chạy test, và cách viết hay sửa chính bộ tài liệu này."}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Quy ước viết code", "a": "style", "x": "envs/ không import torch và không import từ module nào có torch. Lý do ở Kiến trúc . Config là dataclass chỉ chứa siêu tham số; tùy chọn chạy ( model , save_path , device , render ...) là keyword của hàm train. Hàm train in log bằng print , không dùng tqdm, để đọc được cả trong notebook và terminal. Comment và docstring bằng tiếng Việt , theo phong cách notebook gốc. Comment giải thích vì sao hoặc nêu đơn vị, không lặp lại điều code đã nói. Đơn vị rõ ràng : mọi tham số tính theo \"update\" hay \"bước env\" phải ghi trong comment của trường (xem log_every của PPOConfig và DQNConfig ). Giữ hành vi m"}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Test", "a": "tests", "x": "Test nằm ở tests/ , không cần emulator nên chạy nhanh. Cần cài pytest (một lần): pip install -e \"pacman_rl[dev]\" # hoặc: pip install pytest pytest pacman_rl # chạy từ thư mục rel_ms_pacman/ Test hiện có trong tests/test_core.py : Test Kiểm tra test_log_reward_and_events log_reward đúng công thức; count_events đếm đúng viên năng lượng và ma test_network_shapes Hình dạng đầu ra của ActorCriticCNN (forward và act ) và QNetwork test_replay_buffer_stacks_within_episode Chồng 4 frame lặp frame đầu episode, bắt đầu mới ở episode mới, không trộn giữa các env test_save_load_run_roundtrip save_run rồi l"}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Viết test mới", "a": "write-tests", "x": "Test phần thuần : biến đổi reward, hình dạng tensor, logic buffer, lưu/nạp. Tránh gọi make_env hay train_* (cần emulator, chậm). Dùng dữ liệu nhỏ có đáp án tính tay được (như test buffer: frame ghi ở bước t của env e có giá trị 10e + t ). Dùng fixture tmp_path của pytest cho mọi thứ ghi ra đĩa. Thêm test khi sửa lỗi, để lỗi đó không quay lại. import numpy as np from pacman_rl.envs import log_reward def test_log_reward_is_monotonic(): r = log_reward([0, 10, 50, 200, 1600]) assert np.all(np.diff(r) > 0) Ngoài test tự động, mọi thay đổi chạm vào vòng train nên có một lần chạy ngắn bằng CLI ( trai"}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Viết và sửa tài liệu này", "a": "docs", "x": "Tài liệu là các file HTML tĩnh trong docs/html/ , không cần công cụ build. Mở index.html bằng trình duyệt là xem được (kể cả khi mở thẳng file). Thanh bên, mục lục trang, tìm kiếm, nút copy và chuyển sáng/tối đều do assets/docs.js dựng, nên mỗi trang chỉ cần nội dung."}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Thêm một trang", "a": "docs-new", "x": "Sao chép một trang gần giống Ví dụ guides/evaluation.html . Sửa <title> , h1 , nội dung. Đặt data-root và data-page ở thẻ <body> <body data-root=\"../\" data-page=\"guides/ten-trang.html\"> data-root là đường dẫn tương đối từ trang về docs/html/ ( ./ cho trang gốc, ../ cho trang trong thư mục con). data-page khớp với path trong nav.js . Khai báo trong assets/nav.js { path: \"guides/ten-trang.html\", title: \"Tên hiển thị\" } Thứ tự trong nav.js cũng là thứ tự \"Trước/Tiếp\" ở cuối trang. Cho mọi h2 / h3 một id duy nhất Id dùng cho mục lục bên phải, neo liên kết và tìm kiếm. Sinh lại chỉ mục tìm kiếm và "}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Các thành phần có sẵn", "a": "docs-components", "x": "Dùng đúng các lớp CSS này để trang mới nhìn đồng nhất: Thành phần Markup Hộp lưu ý <div class=\"callout note|tip|warn|danger\"><p class=\"callout-title\">Tiêu đề</p><p>...</p></div> Khối code <pre><code class=\"language-python|bash|powershell\">...</code></pre> (tự tô màu, có nút Copy). Văn bản thường: <pre class=\"plain\"><code>...</code></pre> Bảng Bọc <table> trong <div class=\"table-wrap\"> để cuộn ngang trên màn hình nhỏ Tab <div class=\"tabs\"><div class=\"tab\" data-title=\"Tên\">...</div>...</div> Các bước <ol class=\"steps\"><li><h4>Tiêu đề bước</h4>...</li></ol> Thẻ liên kết <div class=\"cards\"><a clas"}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Mẫu một khối tham số", "a": "docs-param", "x": "<section class=\"param\"> <h3 id=\"ten_tham_so\"><code>ten_tham_so</code> <span class=\"type\">int</span> <span class=\"default\">mặc định 128</span></h3> <p>Một hai câu nói tham số là gì.</p> <dl> <dt>Điều khiển</dt><dd>...</dd> <dt>Tăng</dt><dd>...</dd> <dt>Giảm</dt><dd>...</dd> <dt>Khi nào chỉnh</dt><dd>...</dd> </dl> </section>"}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Link mở code trong VS Code", "a": "docs-source-links", "x": "Bạn không cần viết thẻ <a> nào. Khi docs được mở bằng file:// , docs.js tự biến mỗi <code> inline có nội dung đúng bằng một tên có trong assets/source-index.js thành link vscode://file/<đường dẫn>:<dòng> . Tên được nhận gồm: hàm và lớp ở cấp module ( train_ppo , PipelinedEnvs ), hằng viết hoa ( ALGOS , N_ACTIONS ); đường dẫn file tính từ src/pacman_rl/ ( agents/ppo.py , cli.py ); trên trang ppo-config.html và dqn-config.html , tiêu đề của mỗi khối tham số được nối với trường dataclass tương ứng (nhờ thuộc tính data-cfg ở <body> ). source-index.js do build_search_index.py sinh bằng cách quét sr"}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Phong cách viết", "a": "docs-style", "x": "Bám theo code : mọi con số mặc định và công thức phải khớp mã nguồn. Sửa code thì sửa docs trong cùng thay đổi. Nói rõ mức độ chắc chắn : phân biệt \"đã đo/đã chạy\" với \"kinh nghiệm chung\". Đừng đưa số liệu không có thật. Đơn vị đi kèm con số : bước env, update, byte, giây. Một ví dụ chạy được đáng giá hơn một đoạn mô tả. Trước khi đưa code vào tài liệu, hãy chạy nó."}, {"p": "contributing/conventions.html", "t": "Quy ước, test, viết docs", "h": "Danh sách kiểm tra khi gửi thay đổi", "a": "pr-checklist", "x": "Hành vi mặc định không đổi (trừ khi chủ ý, và khi đó ghi rõ). pytest pacman_rl pass; thêm test cho phần mới. Chạy ngắn bằng CLI: train , eval , plot . envs/ vẫn không import torch. Tài liệu cập nhật; build_search_index.py và check_links.py chạy sạch."}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "", "a": "", "x": "Đóng góp Các mở rộng nhỏ hơn một thuật toán: ghi thêm một chỉ số vào log, thêm trường vào config, viết wrapper env, thêm một mạng hay một cách chọn action. Mỗi mục nói rõ file nào cần sửa và những bẫy thường gặp."}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Thêm một chỉ số vào log", "a": "add-metric", "x": ""}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Trong train_ppo", "a": "metric-ppo", "x": "Khóa của log và danh sách giá trị được ghép bằng zip theo thứ tự : log = {\"step\": [], \"ent\": [], \"kl\": [], \"clipfrac\": [], \"v_loss\": [], \"pg_loss\": [], \"pellets\": [], \"ghosts\": []} ... for k, v in zip(log, [global_step, entropy.item(), kl, cf, v_loss.item(), pg_loss.item(), n_pellet, n_ghost]): log[k].append(v) Thêm khóa mới vào cả hai chỗ, cùng vị trí . Ví dụ ghi thêm độ lệch chuẩn của advantage: log = {..., \"pellets\": [], \"ghosts\": [], \"adv_std\": []} ... for k, v in zip(log, [..., n_pellet, n_ghost, adv.std().item()]): log[k].append(v) Hai danh sách lệch vị trí thì không báo lỗi zip dừng ở d"}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Trong train_dqn", "a": "metric-dqn", "x": "Chỉ số DQN được ghi theo log_every (bước env), thường là trung bình tích lũy từ lần ghi trước. Mẫu có sẵn: loss và q_mean được cộng dồn vào loss_acc , q_acc trên GPU (để tránh đồng bộ mỗi bước), rồi chia cho n_acc khi ghi và đặt lại. Làm theo mẫu đó cho chỉ số mới: tạo bộ cộng dồn, cộng trong vòng học, đọc và reset trong khối if step >= next_log ."}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Vẽ chỉ số mới", "a": "metric-plot", "x": "from pacman_rl.plotting import plot_metric plot_metric(runs, \"adv_std\", \"Độ lệch chuẩn của advantage\") Run nào không có khóa đó thì bị bỏ qua (nên vẽ chung PPO và DQN không lỗi). Nhớ ghi khóa mới vào bảng File lưu và log ."}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Thêm một trường vào config", "a": "add-config", "x": "Thêm vào dataclass với giá trị mặc định bảo toàn hành vi cũ và một comment ngắn nêu ý nghĩa, đơn vị: @dataclass class PPOConfig: ... value_clip: float = 0.0 # 0: tắt; >0: cắt thay đổi value trong khoảng này Dòng lệnh tự nhận trường mới qua --set value_clip=0.2 vì _parse_overrides đọc danh sách trường của dataclass. Quy tắc ép kiểu theo kiểu của giá trị mặc định : Kiểu mặc định Cách --set đọc int (và bool , vì bool là con của int ) type(default)(float(value)) : nhận 8 , 2e6 , và với bool là 1 / 0 (không nhận true ) float float(value) str giữ nguyên chuỗi Callable (như reward_fn ) bị từ chối, kh"}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Thêm một hàm reward", "a": "add-reward", "x": "Hàm thuần đặt ở envs/rewards.py (cùng chỗ log_reward ) và nhận/trả mảng numpy. envs/ không được import torch. Hàm có trạng thái thì tạo lớp có __call__ , xem ví dụ chạy được ở Reward shaping . Giữ nguyên nguyên tắc ba loại điểm : hàm reward chỉ đổi reward học, không được ảnh hưởng đến count_events hay game_score (hai thứ này tính từ reward thật, xem )."}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Thêm một wrapper env", "a": "add-wrapper", "x": "Đặt trong envs/wrappers.py (kế EpisodicLife ) và bọc trong make_env ( envs/factory.py ). Quy ước: Chỉ bọc khi học , trong nhánh if episodic_life: , để đánh giá (gọi make_env() không cờ) không bị ảnh hưởng. Không import torch : mỗi process con của env chỉ cần pacman_rl.envs . Dựng được trong process con : PipelinedEnvs dùng functools.partial(make_env, ...) thay cho lambda để hàm tạo env pickle được. Đừng thêm tham số không pickle được vào make_env . Đừng sửa reward nếu muốn count_events còn đúng. Đưa tín hiệu bổ sung qua info rồi để trainer xử lý. Thứ tự bọc có ý nghĩa : FrameStack ngoài cùng, "}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Thêm một mạng", "a": "add-network", "x": "Thêm lớp vào models/networks.py . Dùng lại make_cnn() nếu muốn chung thân CNN. forward nhận uint8 hình (B, 4, 84, 84) và tự chia 255.0 (không chuẩn hóa ở nơi khác). Constructor nhận n_actions làm tham số đầu tiên (để load_model dựng được bằng MODEL_CLASSES[algo](n_actions) ). Xuất ra trong models/__init__.py và thêm vào MODEL_CLASSES với tên thuật toán. Thêm test hình dạng đầu ra (xem test_network_shapes trong tests/test_core.py làm mẫu). class DuelingQNetwork(nn.Module): def __init__(self, n_actions): super().__init__() self.cnn = make_cnn() self.value = nn.Linear(512, 1) self.adv = nn.Linear"}, {"p": "contributing/extend-components.html", "t": "Thêm chỉ số, reward, mạng", "h": "Thêm một cách chọn action khi đánh giá", "a": "add-policy", "x": "Thêm hàm <tên>_policy(model, device, ...) vào evaluation.py , trả về hàm act(obs) -> int . Mẫu: def my_policy(model, device): def act(obs): # obs: np.ndarray uint8 (4,84,84) with torch.no_grad(): return model(torch.as_tensor(obs, device=device).unsqueeze(0)).argmax(1).item() return act Rồi dùng với evaluate / watch . Nếu muốn lệnh eval / play trên CLI dùng được, thêm một nhánh vào cli._policy ."}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "", "a": "", "x": "Bắt đầu Cài đúng thứ tự: môi trường Python, torch bản CUDA, rồi pacman_rl. Làm xong thì chạy ba lệnh kiểm tra ở cuối trang để chắc mọi thứ ổn."}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "Yêu cầu", "a": "requirements", "x": "Thành phần Yêu cầu Ghi chú Python 3.10 trở lên Khai báo ở requires-python trong pyproject.toml . Dự án được phát triển và thử trên Python 3.10. GPU NVIDIA có CUDA (khuyên dùng) Không có GPU vẫn chạy được, nhưng chậm hơn nhiều. get_device() tự chọn cuda nếu có, không thì cpu . CPU Càng nhiều nhân càng tốt Mặc định mở 16 process env. Ít nhân thì giảm n_envs (xem chọn cỡ theo máy ). RAM Tối thiểu khoảng 8 GB, khuyên 16 GB DQN với buffer_size mặc định (200,000) cần khoảng 1.4 GB cho buffer, chưa kể 16 process env. Hệ điều hành Windows (đã dùng thực tế) Code không dùng API riêng của Windows nên Lin"}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "Thư viện phụ thuộc", "a": "deps", "x": "Khai báo trong pyproject.toml , pip sẽ tự cài: Gói Phiên bản Vai trò numpy < 2 Mảng, replay buffer. Ghim dưới 2 để khớp với gymnasium 0.29 và torch 2.3. gymnasium == 0.29.1 API env, vector env, wrapper. Ghim cứng vì pacman_rl dùng gym.wrappers.FrameStack và AtariPreprocessing của bản này. ale-py ≥ 0.9, < 0.11 Emulator Atari, đã kèm sẵn ROM Ms. Pacman. opencv-python bất kỳ Resize và chuyển xám khung hình xuống 84x84. matplotlib bất kỳ Vẽ biểu đồ. pytest tùy chọn ( [dev] ) Chạy test. torch không nằm trong danh sách trên Cố ý. Nếu để pip tự kéo torch, nó sẽ cài bản CPU và đè lên bản CUDA bạn đã c"}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "Các bước cài", "a": "steps", "x": "Tạo môi trường Python Dùng conda (như dự án đang dùng) hoặc venv đều được. conda create -n rel_pacman python=3.10 conda activate rel_pacman python -m venv .venv .venv\\Scripts\\activate python3 -m venv .venv source .venv/bin/activate Cài torch bản CUDA Bản dự án đang dùng là torch 2.3.1 với CUDA 12.1: pip install torch==2.3.1 --index-url https://download.pytorch.org/whl/cu121 Máy không có GPU NVIDIA thì cài bản CPU: pip install torch==2.3.1 . Cài pacman_rl Chạy từ thư mục rel_ms_pacman/ (thư mục chứa pacman_rl/ ): pip install -e pacman_rl Cờ -e (editable) nghĩa là sửa code trong src/ có hiệu lực"}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "Kiểm tra cài đặt", "a": "verify", "x": "Chạy lần lượt ba lệnh. Mỗi lệnh kiểm tra một tầng khác nhau."}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "1. Import được thư viện", "a": "verify-import", "x": "python -c \"import pacman_rl; print(pacman_rl.__version__)\" 0.1.0"}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "2. Nhận đúng thiết bị tính toán", "a": "verify-device", "x": "python -c \"from pacman_rl import get_device, describe_device; print(describe_device(get_device()))\" cuda | NVIDIA GeForce RTX 3070 Ti Laptop GPU Nếu in cpu | CPU trong khi máy có GPU, torch bạn cài là bản CPU. Cài lại theo bước 2."}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "3. Emulator và ROM hoạt động", "a": "verify-env", "x": "python -c \"from pacman_rl.envs import make_env; e = make_env(); obs, _ = e.reset(seed=0); print(obs.shape, obs.dtype)\" A.L.E: Arcade Learning Environment (version 0.10.2+c9d4b19) [Powered by Stella] (4, 84, 84) uint8 Hai dòng A.L.E ... và [Powered by Stella] là thông báo bình thường của emulator. Khi train với 16 env bạn sẽ thấy chúng lặp lại nhiều lần, mỗi process con in một lần. Trên Windows, script riêng cần if __name__ == \"__main__\" Env song song dùng multiprocessing kiểu spawn : process con import lại file chính. Nếu bạn viết file .py gọi train_ppo(...) , hãy đặt lệnh gọi trong khối if __"}, {"p": "getting-started/installation.html", "t": "Cài đặt", "h": "Lệnh pacman-rl", "a": "entrypoint", "x": "Cài xong còn có lệnh pacman-rl (nằm trong Scripts/ của môi trường), tương đương với python -m pacman_rl . Hai dạng sau chạy y hệt nhau: pacman-rl train ppo --steps 100000 python -m pacman_rl train ppo --steps 100000"}, {"p": "getting-started/quickstart.html", "t": "Chạy thử trong 10 phút", "h": "", "a": "", "x": "Bắt đầu Train PPO một lần thật ngắn, chấm điểm, vẽ biểu đồ và xem agent chơi. Mục đích là xác nhận cả chuỗi hoạt động, chưa phải để ra một agent giỏi. Trước khi bắt đầu Đã cài xong theo Cài đặt và môi trường đang bật (ví dụ conda activate rel_pacman ). Các lệnh chạy ở thư mục bất kỳ; file lưu vào runs/ của thư mục hiện tại."}, {"p": "getting-started/quickstart.html", "t": "Chạy thử trong 10 phút", "h": "Bước 1. Train ngắn", "a": "train", "x": "50,000 bước là rất ít (cỡ 2.5% so với cấu hình PPO mặc định) nhưng đủ để thấy đường học bắt đầu nhúc nhích: python -m pacman_rl train ppo --steps 50000 --set log_every=5 --name quick from pacman_rl import PPOConfig, train_ppo, save_run, get_device device = get_device() cfg = PPOConfig(total_steps=50_000, log_every=5) result = train_ppo(cfg, save_path=\"runs/quick.pt\", device=device) save_run(result, \"runs\", \"quick\") log_every=5 để in log mỗi 5 update (mặc định là 50, quá thưa cho một lần chạy ngắn). Kết quả thật trên một máy RTX 3070 Ti Laptop: device: cuda | NVIDIA GeForce RTX 3070 Ti Laptop G"}, {"p": "getting-started/quickstart.html", "t": "Chạy thử trong 10 phút", "h": "Bước 2. Chấm điểm", "a": "eval", "x": "python -m pacman_rl eval ppo --name quick --episodes 3 PPO trên 3 ván: mean 453 | std 191 | max 720 Điểm: [280, 360, 720] Đây là điểm thật của game đầy đủ 3 mạng, dùng seed cố định cho env (1000, 1001, ...), nên mọi model được chấm trên cùng các ván xuất phát. Tuy nhiên PPO mặc định lấy mẫu action từ policy nên điểm vẫn dao động giữa các lần chạy; thêm --greedy nếu muốn kết quả ổn định hơn. Xem Đánh giá ."}, {"p": "getting-started/quickstart.html", "t": "Chạy thử trong 10 phút", "h": "Bước 3. Vẽ biểu đồ", "a": "plot", "x": "python -m pacman_rl plot ppo:quick --out quick.png Ảnh thật do lệnh trên tạo ra. Trái: điểm từng ván (chấm mờ) và trung bình trượt 20 ván. Giữa: entropy giảm dần. Phải: trống ý nghĩa vì lần chạy quá ngắn. Biểu đồ thứ ba gần như vô nghĩa với run ngắn Nó chia số lần ăn ma cho số viên năng lượng theo từng khoảng 100,000 bước. Run 50,000 bước chỉ có một khoảng nên đường thẳng trơ trọi như trên. Với run từ vài trăm nghìn bước trở lên thì đọc bình thường."}, {"p": "getting-started/quickstart.html", "t": "Chạy thử trong 10 phút", "h": "Bước 4. Xem agent chơi", "a": "watch", "x": "python -m pacman_rl play ppo --name quick --episodes 2 Lệnh này mở cửa sổ game nên cần có màn hình. Sau 50,000 bước agent còn chơi khá vụng; xem để chắc rằng pipeline từ model tới màn hình hoạt động."}, {"p": "getting-started/quickstart.html", "t": "Chạy thử trong 10 phút", "h": "Làm gì tiếp theo", "a": "next", "x": "Train thật: Setup và chạy huấn luyện (mặc định PPO 2 triệu bước, DQN 10 triệu bước). Hiểu các cột log và tham số: PPOConfig , DQNConfig . Vì sao có 16 env mà chỉ một policy: Env song song và pipeline ."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "", "a": "", "x": "Hướng dẫn Điểm in ra lúc train chưa phải thước đo cuối cùng. Đánh giá chạy riêng, theo cách công bằng và lặp lại được: game đầy đủ 3 mạng, điểm thật, seed cố định."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Vì sao cần bước đánh giá riêng", "a": "why", "x": "Lúc train, agent chơi bằng policy đang thay đổi, và còn có khám phá (lấy mẫu hoặc epsilon cao). Env lúc train dùng EpisodicLife (mất mạng = hết episode); đánh giá chạy trọn ván 3 mạng như game thật. Điểm đánh giá là điểm thật , không qua reward_fn , nên so sánh được giữa các cấu hình reward khác nhau."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Chấm điểm bằng dòng lệnh", "a": "cli", "x": "python -m pacman_rl eval ppo --episodes 20 python -m pacman_rl eval ppo --episodes 20 --greedy python -m pacman_rl eval dqn --name dqn_seed1 --eps 0.01 PPO trên 20 ván: mean <trung bình> | std <độ lệch chuẩn> | max <ván cao nhất> Điểm: [<điểm từng ván>] Tùy chọn đầy đủ ở CLI: eval ."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Chấm điểm trong Python", "a": "python", "x": "from pacman_rl import load_run, ppo_policy, dqn_policy, evaluate, random_baseline, get_device from pacman_rl.plotting import plot_eval device = get_device() ppo = load_run(\"runs\", \"ms_pacman_ppo\", \"ppo\", device) dqn = load_run(\"runs\", \"ms_pacman_dqn\", \"dqn\", device) results = { \"Random\": random_baseline(5), \"PPO\": evaluate(ppo_policy(ppo.model, device), n_episodes=10), \"DQN\": evaluate(dqn_policy(dqn.model, device, eps=0.05), n_episodes=10), } plot_eval(results, save_path=\"eval.png\") # in bảng mean/std/max và vẽ boxplot random_baseline cho biết agent không học gì đạt bao nhiêu điểm. Nếu agent c"}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Các lựa chọn khi chấm điểm", "a": "settings", "x": ""}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Số ván", "a": "episodes", "x": "Điểm mỗi ván dao động mạnh (độ lệch chuẩn thường lớn so với trung bình). 10 ván cho cảm nhận ban đầu; muốn so sánh hai agent gần nhau thì dùng 30 ván trở lên và nhìn cả std , đừng chỉ nhìn trung bình."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Seed", "a": "seeds", "x": "evaluate dùng seed cố định: ván thứ i dùng seed 1000 + i . Mọi agent được chấm trên cùng các tình huống xuất phát , nên so sánh công bằng. Đổi seed=... nếu muốn một bộ ván khác. Seed cố định chưa phải kết quả cố định Seed chỉ cố định phía env. PPO mặc định lấy mẫu action, nên lần chạy sau cho điểm hơi khác. Nếu cần đúng từng con số (ví dụ viết báo cáo), dùng greedy=True / --greedy : khi đó không còn yếu tố ngẫu nhiên nào ở phía policy."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "PPO: lấy mẫu hay greedy", "a": "modes", "x": "Lấy mẫu (mặc định): chơi đúng như lúc train. Phản ánh policy đã học. Greedy : luôn chọn action có xác suất cao nhất. Thường ổn định hơn nhưng đôi khi kẹt lặp một chuyển động. Hãy thử cả hai và báo cáo rõ bạn dùng cái nào."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "DQN: epsilon khi chơi", "a": "eps", "x": "Mặc định eps=0.05 . Greedy tuyệt đối ( eps=0 ) có thể làm agent kẹt; một chút ngẫu nhiên giúp thoát. Dùng cùng một eps cho mọi lần so sánh."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "max_steps", "a": "max_steps", "x": "Mỗi ván bị cắt sau max_steps=4500 bước (18,000 frame, khoảng 5 phút game) để tránh chạy vô hạn khi agent kẹt. Agent rất giỏi có thể chạm trần này. Khi đó điểm bị cắt thấp hơn thực tế; tăng max_steps trong Python (CLI chưa có tùy chọn này). evaluate(act, n_episodes=10, max_steps=20000)"}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Tự viết policy", "a": "custom", "x": "Một policy chỉ là hàm act(obs) -> int với obs là np.ndarray uint8 hình (4, 84, 84) (hoặc (12, 84, 84) với model RGB; ppo_policy / dqn_policy tự cho evaluate / watch biết để dựng đúng env). Nhờ vậy bạn có thể đo bất kỳ thứ gì bằng cùng cách: import random from pacman_rl import evaluate def always_right(obs): return 2 # RIGHT def jittery(obs): return random.choice([2, 3]) # RIGHT hoặc LEFT print(evaluate(always_right, n_episodes=5)) print(evaluate(jittery, n_episodes=5)) Bảng chỉ số action ở Môi trường và các loại điểm . Ví dụ khác: policy từ một mạng khác, tập luật, hoặc ensemble nhiều model (t"}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Xem agent chơi", "a": "watch", "x": "python -m pacman_rl play ppo --greedy --episodes 3 from pacman_rl import watch, ppo_policy watch(ppo_policy(ppo.model, device), episodes=2) # in điểm từng ván Cần có màn hình (mở cửa sổ game). Quan sát hành vi bằng mắt thường hay lộ ra điều mà số điểm không nói: agent đi vòng vòng, né ma kém, bỏ qua viên năng lượng..."}, {"p": "guides/evaluation.html", "t": "Đánh giá và xem agent chơi", "h": "Báo cáo kết quả", "a": "report", "x": "Một báo cáo có thể tin cậy cần có: số ván, seed đánh giá, chế độ chọn action ( greedy hoặc eps ), cả mean lẫn std hoặc boxplot, mốc random_baseline , và nếu có thể, kết quả của nhiều seed train (không chỉ nhiều ván chơi của một model)."}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "", "a": "", "x": "Hướng dẫn Từng tham số làm gì đã có ở PPOConfig và DQNConfig . Trang này trả lời câu hỏi thực tế hơn: run của tôi trông như thế này, nên chỉnh gì trước? Mức độ chắc chắn của trang này Các ngưỡng và gợi ý dưới đây là kinh nghiệm chung của RL trên Atari, không phải kết quả đo trên dự án này. Hãy coi chúng là giả thuyết để thử, và kiểm chứng bằng nhiều seed."}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "Năm nguyên tắc", "a": "rules", "x": "Đổi từng thứ một. Đổi hai tham số cùng lúc thì không biết cái nào gây ra khác biệt. Dùng nhiều seed. Một lần chạy RL nhiễu đến mức hai seed của cùng cấu hình có thể khác nhau xa. Ít nhất 3 seed trước khi kết luận. Giữ total_steps cố định khi so sánh. Với PPO, lr giảm về 0 theo tổng số bước; với DQN, epsilon giảm theo tỷ lệ của tổng số bước. Đổi total_steps là đổi cả hai lịch này. Nhìn log, không chỉ điểm. Điểm rất nhiễu; entropy, KL, q_mean báo lỗi sớm hơn nhiều. Xem Vẽ biểu đồ, đọc log . Ghi lại cấu hình bằng cách đặt tên run mô tả được nó ( ppo_lr1e4_c2_0.02_s1 ), vì thư viện không lưu confi"}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "PPO: chỉnh theo thứ tự này", "a": "ppo-order", "x": "# Tham số Vì sao đứng ở đây 1 lr Nhạy nhất; sai lr thì mọi thứ khác không còn ý nghĩa. 2 c2 Quyết định agent khám phá bao nhiêu trước khi chốt chiến thuật. 3 n_envs × n_steps Quy định cỡ batch; chủ yếu đổi theo phần cứng. 4 epochs , clip_eps Hai núm \"độ táo bạo\" của mỗi update. 5 gamma , lam , c1 , max_grad Giá trị chuẩn thường đã ổn; chỉ đụng tới khi có bằng chứng."}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "PPO: triệu chứng và việc nên thử", "a": "ppo-symptoms", "x": "Bạn thấy Có thể là Thử entropy đứng gần 2.19 rất lâu, điểm không tăng Học quá chậm, hoặc c2 quá lớn khiến policy mãi ngẫu nhiên Tăng lr (ví dụ 5e-4) hoặc giảm c2 (0.005) entropy sụt rất nhanh về gần 0, điểm dừng sớm Chốt sớm vào chiến thuật kém (thiếu khám phá) Tăng c2 (0.02), giảm lr kl thường xuyên lớn (khoảng > 0.05) hoặc clipfrac thường > 0.3 Mỗi update đi quá xa Giảm lr , giảm epochs , hoặc giảm clip_eps clipfrac luôn ≈ 0 và kl rất nhỏ, học chậm Update quá rụt rè Tăng lr hoặc epochs Điểm tăng rồi sụp đột ngột Bất ổn: lr quá lớn hoặc dữ liệu một lần xấu Giảm lr ; kiểm tra kl trước chỗ sụp "}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "DQN: triệu chứng và việc nên thử", "a": "dqn-symptoms", "x": "Bạn thấy Có thể là Thử q_mean tăng vô độ, loss nhảy lớn Ước lượng Q phân kỳ (DQN gốc dễ đánh giá Q quá cao) Giảm lr , tăng target_update , hoặc dùng Double DQN Điểm không tăng dù eps đã về eps_end Chưa học được, hoặc kẹt trong thói quen Kiểm tra q_mean / loss ; thử tăng eps_end lên 0.1 Điểm tốt khi eps cao nhưng tệ đi khi eps giảm Agent chưa khai thác tốt Kéo dài đoạn giảm: tăng eps_frac Chạy chậm dần, RAM đầy buffer_size quá lớn so với RAM trống Giảm buffer_size , đóng ứng dụng khác log rỗng sau run thử total_steps < log_every Đặt log_every nhỏ, ví dụ --set log_every=1000"}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "DQN: giữ tỷ lệ tái sử dụng khi đổi n_envs", "a": "dqn-ratio", "x": "Mỗi vòng DQN thu n_envs mẫu mới và học updates_per_iter × batch_size mẫu. Tỷ lệ tái sử dụng bằng updates_per_iter × batch_size / n_envs (mặc định 8, đúng với DQN gốc). Đổi n_envs mà quên điều chỉnh sẽ làm tỷ lệ này trôi đi, và hành vi học thay đổi theo. Đổi thành Giữ tỷ lệ 8 bằng n_envs=8 batch_size=64 (hoặc giữ 128 và đặt updates_per_iter=1 để ratio = 16) n_envs=32 batch_size=256 (hoặc updates_per_iter=2 với batch_size=128 ) python -m pacman_rl train dqn --set n_envs=8 batch_size=64"}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "PPO: giữ cỡ batch khi đổi n_envs", "a": "ppo-batch", "x": "Với PPO, batch là n_envs × n_steps . Máy yếu hơn thì giảm n_envs và tăng n_steps theo tỷ lệ nghịch để batch (và số gradient step mỗi update) không đổi: python -m pacman_rl train ppo --set n_envs=8 n_steps=256 # batch vẫn 2048 python -m pacman_rl train ppo --set n_envs=4 n_steps=512 # batch vẫn 2048 n_steps lớn hơn cũng nghĩa là mỗi env đi dài hơn giữa hai lần cập nhật, nên không hoàn toàn tương đương, nhưng là điểm xuất phát hợp lý."}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "Thử nhanh bằng run ngắn", "a": "short-runs", "x": "PPO --steps 100000 đến 200000 đủ để thấy entropy bắt đầu giảm và điểm nhúc nhích. Đặt log_every nhỏ (5 đến 10) để thấy log. Đừng so điểm của run ngắn với run dài: lịch lr đã khác nhau. DQN cần ít nhất vài trăm nghìn bước mới có tín hiệu rõ; khi thử ngắn, giảm learning_starts , target_update , log_every cho cân đối: python -m pacman_rl train dqn --steps 300000 --set learning_starts=5000 target_update=2000 log_every=20000"}, {"p": "guides/hyperparameters.html", "t": "Chọn và chỉnh tham số", "h": "Vài điểm xuất phát để thử", "a": "starting-points", "x": "Chưa kiểm chứng trên dự án này; dùng làm giả thuyết đầu tiên, so với mặc định bằng nhiều seed: Mục tiêu Lệnh gợi ý Khám phá nhiều hơn (PPO) --set c2=0.02 Ổn định hơn (PPO) --set lr=1e-4 epochs=3 Máy 8 nhân (PPO) --set n_envs=8 n_steps=256 Ít RAM (DQN) --set buffer_size=100000 Khám phá lâu hơn (DQN) --set eps_frac=0.1"}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "", "a": "", "x": "Hướng dẫn Vẽ đường học của một hay nhiều run, và quan trọng hơn: biết mỗi con số nói gì để phát hiện run hỏng sớm, trước khi tốn hàng giờ."}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "Vẽ nhanh", "a": "quick", "x": "python -m pacman_rl plot ppo dqn --out curves.png python -m pacman_rl plot ppo:base_s0 ppo:penalty_s0 --out compare.png from pacman_rl import load_run, random_baseline from pacman_rl.plotting import plot_training, plot_events, plot_metric runs = {\"PPO\": load_run(\"runs\", \"ms_pacman_ppo\", \"ppo\"), \"DQN\": load_run(\"runs\", \"ms_pacman_dqn\", \"dqn\")} plot_training(runs, random_scores=random_baseline(5), save_path=\"curves.png\") plot_events(runs) # viên năng lượng / ma ăn được mỗi 100k bước plot_metric(runs, \"q_mean\") # một chỉ số bất kỳ trong log; run nào không có thì bỏ qua runs là dict nhãn → TrainRe"}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "Sáu biểu đồ mặc định", "a": "default", "x": "Ảnh thật từ một run PPO 50,000 bước. Run này quá ngắn nên biểu đồ phải trống ý nghĩa; các biểu đồ có đầy đủ nội dung khi run dài hơn. Ảnh chụp từ bản cũ chỉ có ba biểu đồ đầu; bản hiện tại là lưới 2x3 với sáu biểu đồ như bảng dưới. Biểu đồ Hiển thị Đọc thế nào Điểm theo số bước Chấm mờ: điểm từng ván. Đường: trung bình trượt 20 ván. Đường đi lên là agent đang học. Chấm mờ rải rộng là bình thường: điểm mỗi ván dao động lớn. Entropy (PPO) Độ ngẫu nhiên của policy. Xem Đọc log PPO . DQN không có chỉ số này nên không xuất hiện. Bước sống mỗi lượt Số bước env trung bình mỗi lượt chơi (một mạng), th"}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "Đọc log PPO", "a": "read-ppo", "x": "Các chỉ số này được ghi mỗi update, lấy từ minibatch cuối cùng, nên gợn sóng là bình thường; hãy nhìn xu hướng . Chỉ số Nó đo gì Dấu hiệu khỏe Dấu hiệu đáng ngờ ent (entropy) Độ ngẫu nhiên của policy. Tối đa ln 9 ≈ 2.197 . Bắt đầu quanh 2.2, giảm dần và đều theo thời gian. Đứng yên ≈ 2.19 mãi: học quá chậm hoặc c2 quá lớn. Sụt gần 0 rất sớm: chốt sớm, thiếu khám phá. kl Policy mới lệch bao xa so với policy lúc thu dữ liệu (xấp xỉ). Có thể âm nhẹ do nhiễu. Nhỏ, cỡ vài phần nghìn đến vài phần trăm. Thường xuyên lớn (khoảng > 0.05): update quá mạnh. clipfrac Tỷ lệ mẫu mà tỷ lệ policy bị cắt bởi c"}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "Đọc log DQN", "a": "read-dqn", "x": "Các chỉ số được ghi mỗi log_every bước env; loss và q_mean là trung bình từ lần ghi trước. Chỉ số Nó đo gì Dấu hiệu khỏe Dấu hiệu đáng ngờ eps Xác suất chọn action ngẫu nhiên. Giảm tuyến tính từ eps_start về eps_end rồi phẳng. Không đổi (thường do total_steps quá nhỏ hoặc eps_frac sai). loss Huber loss giữa Q và mục tiêu Bellman. Dao động ở mức thấp, tăng nhẹ theo thời gian cũng thường gặp (mục tiêu khó dần). Nhảy lớn đột ngột, hoặc nan sau khi đã bắt đầu học. q_mean Giá trị Q trung bình của các action đã chọn (đơn vị của reward học , không phải điểm). Tăng dần và chậm khi agent học được. Tăng"}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "Đọc chỉ số ăn viên năng lượng và ma", "a": "read-events", "x": "pellets , ghosts và deaths (tổng số mạng đã mất) trong log là tổng tích lũy từ đầu run. plot_training đã dùng deaths cho ba biểu đồ theo lượt; plot_events vẫn chỉ vẽ pellets và ghosts . plot_events đổi thành số lượng trong mỗi khoảng bin_size bước để dễ thấy xu hướng: Viên năng lượng / khoảng tăng: agent tìm tới các viên năng lượng thường xuyên hơn. Ma / khoảng tăng: agent biết ăn ma khi ma sợ hãi. Ma trên viên năng lượng : mỗi viên cho phép ăn tối đa 4 con ma liên tiếp (200, 400, 800, 1600). Tỷ lệ tăng nghĩa là agent khai thác tốt hơn mỗi viên. Đây là phép đếm gần đúng (xem Đếm viên năng lượn"}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "So sánh nhiều run", "a": "compare", "x": "Đưa nhiều run vào cùng runs , nhãn là tên bạn đặt: runs = {\"base\": load_run(\"runs\", \"ppo_base_s0\", \"ppo\"), \"c2=0.02\": load_run(\"runs\", \"ppo_c2_0.02_s0\", \"ppo\")} plot_training(runs, save_path=\"compare.png\") Khi có nhiều run trong một thư mục, compare() nạp và vẽ giúp. Bỏ names thì lấy tất cả run .pt trong directory (xem tên bằng list_runs ): from pacman_rl.plotting import compare from pacman_rl.runs import list_runs list_runs(\"runs\") # tên mọi run trong thư mục runs = compare(directory=\"runs\", metrics=(\"ent\",)) # hoặc compare([\"ppo_a\", \"ppo_b\"]) Ngoài plot_training , compare vẽ thêm bảng xếp hạ"}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "Trung bình nhiều seed", "a": "seeds", "x": "Một run đơn lẻ không đủ tin cậy. Đoạn sau nội suy đường trung bình trượt của từng seed về cùng một trục bước rồi vẽ trung bình kèm dải ±1 độ lệch chuẩn: import numpy as np import matplotlib.pyplot as plt from pacman_rl import load_run from pacman_rl.plotting import score_curve grid = np.linspace(0, 2_000_000, 200) # trục bước chung cho mọi seed curves = [] for s in (0, 1, 2): r = load_run(\"runs\", f\"ppo_base_s{s}\", \"ppo\") x, y = score_curve(r.episodes, w=20) curves.append(np.interp(grid, x, y)) # nội suy về cùng trục mean, std = np.mean(curves, axis=0), np.std(curves, axis=0) plt.plot(grid, mea"}, {"p": "guides/plotting.html", "t": "Vẽ biểu đồ, đọc log", "h": "Vẽ chỉ số của riêng bạn", "a": "own-metrics", "x": "import matplotlib.pyplot as plt fig, ax = plt.subplots(1, 2, figsize=(11, 4)) plot_metric(runs, \"kl\", \"KL\", ax=ax[0]) plot_metric(runs, \"clipfrac\", \"Tỷ lệ bị cắt\", ax=ax[1]) fig.savefig(\"diagnostics.png\", dpi=150) Thêm chỉ số mới vào log để vẽ được: Thêm chỉ số vào log ."}, {"p": "guides/reward-shaping.html", "t": "Reward shaping", "h": "", "a": "", "x": "Hướng dẫn Đổi tín hiệu thưởng mà agent học từ đó (phạt mỗi bước, phạt đứng bí, thưởng thêm...) mà vẫn giữ điểm báo cáo là điểm thật của game."}, {"p": "guides/reward-shaping.html", "t": "Reward shaping", "h": "Cơ chế: reward_fn", "a": "how", "x": "Cả PPOConfig và DQNConfig có trường reward_fn . Mỗi bước, trainer lấy reward thật của một nhóm env (mảng độ dài n_envs / 2 ), gọi reward_fn để ra reward học , và chỉ dùng kết quả đó cho gradient. Bị reward_fn ảnh hưởng? Gradient / mục tiêu học Có Điểm cả ván ( episodes , avg score(20) ) Không, luôn là điểm thật Số viên năng lượng, số ma ( pellets , ghosts ) Không, tính từ reward thật Điểm khi eval Không, đánh giá chỉ cộng reward thật Nhờ vậy bạn đổi reward thoải mái mà vẫn so sánh công bằng các cấu hình trên cùng một thang điểm. Mặc định là log_reward : log1p(r / 10) . Hàm của bạn nhận mảng re"}, {"p": "guides/reward-shaping.html", "t": "Reward shaping", "h": "Ví dụ 1: phạt nhỏ mỗi bước (hàm thuần)", "a": "step-penalty", "x": "Đơn giản nhất, không cần trạng thái: from functools import partial from pacman_rl import PPOConfig, train_ppo from pacman_rl.envs import log_reward def log_reward_with_step_penalty(r, penalty=0.01): return log_reward(r) - penalty cfg = PPOConfig(reward_fn=partial(log_reward_with_step_penalty, penalty=0.02)) train_ppo(cfg, save_path=\"runs/ppo_penalty.pt\") Đặt hàm ở cấp module và dùng partial thay cho lambda để về sau lưu/ghi lại config dễ hơn. Chọn độ lớn phạt cẩn thận So với thang reward học (chấm 0.69), phạt 0.02 mỗi bước là nhỏ nhưng cộng dồn: sau 100 bước không ăn gì là −2. Phạt quá lớn khi"}, {"p": "guides/reward-shaping.html", "t": "Reward shaping", "h": "Ví dụ: phạt mất mạng (death_penalty)", "a": "death-penalty", "x": "Không cần viết hàm. Cả PPOConfig và DQNConfig có trường death_penalty (mặc định 0.0 ). Ở bước agent vừa mất một mạng, trainer tính reward_học = reward_fn(reward) - death_penalty * died , với died lấy từ PipelinedEnvs.recv (dựa trên info[\"life_lost\"] do EpisodicLife ghi). cfg = PPOConfig(death_penalty=2.5) train_ppo(cfg, save_path=\"runs/ppo_death.pt\") Như mọi reward shaping, phạt này chỉ đổi reward học; điểm báo cáo, pellets , ghosts vẫn tính từ reward thật. Thang tham chiếu: viên năng lượng ≈ 1.79, ma ≈ 3.0 đến 5.1, nên 1 đến 3 là mức hợp lý để bắt đầu."}, {"p": "guides/reward-shaping.html", "t": "Reward shaping", "h": "Phạt mỗi bước và lịch trình tăng dần (PPO)", "a": "step-penalty", "x": "PPOConfig còn có step_penalty (mặc định 0.0 ): trừ một lượng cố định ở mỗi bước env, nên reward học là reward_fn(reward) - step_penalty - death_penalty * died . Đừng dùng cùng một reward_fn đã tự trừ phạt mỗi bước, vì sẽ bị phạt hai lần. Để phạt nhẹ lúc đầu rồi tăng dần (curriculum), đặt penalty_schedule : hàm tiến_độ (0 đến 1) -> (death_penalty, step_penalty) , tính lại mỗi update. piecewise_penalty dựng lịch trình nội suy tuyến tính giữa các mốc (tiến_độ, death_penalty, step_penalty) ; ngoài khoảng mốc thì giữ giá trị mốc đầu / cuối. from pacman_rl import PPOConfig, piecewise_penalty, train_"}, {"p": "guides/reward-shaping.html", "t": "Reward shaping", "h": "Ví dụ 2: phạt khi \"đứng bí\" (cần trạng thái)", "a": "stateful", "x": "Ý tưởng: không phạt đều mỗi bước, chỉ phạt khi một env đã đi quá patience bước liên tiếp mà không có reward dương. Ít can thiệp hơn phạt đều. Việc này cần nhớ số bước đứng bí của từng env, nên một hàm thuần không đủ; ta dùng một object có __call__ . import numpy as np from pacman_rl import PPOConfig, train_ppo from pacman_rl.envs import log_reward class StuckPenalty: \"\"\"reward_fn có trạng thái: log_reward, trừ thêm `penalty` mỗi bước khi một env đã `patience` bước liên tiếp không có reward dương. Mỗi nhóm env có bộ đếm riêng.\"\"\" def __init__(self, group_size, n_groups=2, patience=50, penalty=0"}, {"p": "guides/reward-shaping.html", "t": "Reward shaping", "h": "Cách chính xác hơn: wrapper env (chưa có trong thư viện)", "a": "wrapper", "x": "Nếu cần reset đúng khi mất mạng, cách bền hơn là làm ở tầng env, nơi biết rõ từng bước và từng cái chết: Viết StuckPenalty(gym.Wrapper) trong envs/wrappers.py , đếm số bước không có reward dương, reset khi terminated , và trả thêm info[\"shaping\"] (không sửa reward , để count_events vẫn đếm đúng). Bọc nó trong make_env chỉ khi episodic_life=True (lúc học). Đánh giá gọi make_env() không có cờ đó nên không bị ảnh hưởng. Cho PipelinedEnvs.recv trả thêm phần shaping để trainer cộng vào reward học. Việc này sửa chữ ký recv (hiện đã trả thêm died cho death_penalty ) nên chạm tới cả hai trainer; xem T"}, {"p": "guides/reward-shaping.html", "t": "Reward shaping", "h": "So sánh có kiểm soát", "a": "compare", "x": "Chạy mỗi cấu hình (không phạt, phạt mỗi bước, phạt đứng bí) với ít nhất 3 seed. Đặt tên run mô tả được: ppo_base_s0 , ppo_step002_s0 , ppo_stuck_s0 . So điểm bằng eval (điểm thật, cùng seed ván) và bằng biểu đồ ma/viên năng lượng để xem hành vi có đổi không. Chú ý tương tác với EpisodicLife : phạt thời gian cộng với việc chết cắt hết reward tương lai có thể làm agent liều lĩnh hoặc né ma kém hơn. Luôn so cả có và không có phạt. python -m pacman_rl plot ppo:ppo_base_s0 ppo:ppo_step002_s0 ppo:ppo_stuck_s0 --out compare.png Vì reward_fn không đặt được từ dòng lệnh, các run có reward riêng phải tr"}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "", "a": "", "x": "Hướng dẫn Từ lúc quyết định train đến lúc có file kết quả: chọn cách chạy, chỉnh cấu hình cho vừa máy, theo dõi, dừng giữa chừng, train tiếp và chạy nhiều seed để so sánh."}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Chọn cách chạy", "a": "choose", "x": "Dòng lệnh Python / notebook Hợp với Chạy dài, chạy nhiều cấu hình, để máy chạy qua đêm Thử nghiệm, vẽ và xem ngay, tự viết reward Đổi tham số --set lr=1e-4 c2=0.02 PPOConfig(lr=1e-4, c2=0.02) Tự lưu cả 3 file Có, khi train xong hoặc khi Ctrl+C Bạn gọi save_run Tự viết reward_fn Không (chỉ qua Python) Có Train tiếp từ model cũ Chưa hỗ trợ Có, model=..."}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Trước khi bấm chạy", "a": "before", "x": "Kiểm tra thiết bị : python -c \"from pacman_rl import *; print(describe_device(get_device()))\" phải ra cuda | ... nếu bạn có GPU. Đóng bớt ứng dụng nặng , nhất là khi train DQN: buffer 1.4 GB và 16 process env cạnh tranh RAM. Tốc độ DQN dao động nhiều theo RAM còn trống. Chọn cỡ n_envs theo máy, xem bên dưới . Biết mình muốn gì : hãy chạy trước bản ngắn 50,000 bước để chắc pipeline ổn rồi mới bỏ hàng giờ cho bản dài."}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Train bằng dòng lệnh", "a": "cli", "x": "# cấu hình mặc định (PPO 2 triệu bước, DQN 10 triệu bước) python -m pacman_rl train ppo python -m pacman_rl train dqn # đổi số bước, seed, tên run, thư mục lưu python -m pacman_rl train ppo --steps 5000000 --seed 1 --name ppo_s1 --out runs # ghi đè bất kỳ siêu tham số nào python -m pacman_rl train ppo --set lr=1e-4 n_envs=8 n_steps=256 c2=0.02 Khi chạy, lệnh in thiết bị và toàn bộ config đang dùng (trừ reward_fn ) lên dòng đầu. Đọc dòng này để chắc --set đã có hiệu lực. Kết quả ghi vào --out (mặc định runs/ , tự tạo nếu chưa có), ba file mang tên --name (mặc định ms_pacman_ppo hoặc ms_pacman_d"}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Train bằng Python", "a": "python", "x": "from pacman_rl import PPOConfig, train_ppo, save_run, get_device device = get_device() cfg = PPOConfig(total_steps=2_000_000, lr=2.5e-4, seed=0) result = train_ppo(cfg, save_path=\"runs/ppo.pt\", device=device) # TrainResult(model, log, episodes) save_run(result, \"runs\", \"ppo\") # ghi 3 file train_ppo và train_dqn nhận cùng bộ tham số chạy. Các tham số này không nằm trong Config vì chúng không làm thay đổi kết quả học: Tham số Mặc định Ý nghĩa cfg None PPOConfig / DQNConfig . Bỏ trống thì dùng mặc định. model None Mạng có sẵn để train tiếp. None thì tạo mới. Xem Train tiếp . save_path None Đường "}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Theo dõi trong lúc train", "a": "watching", "x": ""}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Dòng log", "a": "log-lines", "x": "PPO in một dòng mỗi log_every update ; DQN in mỗi log_every bước env (đơn vị khác nhau, xem đơn vị ). Dấu hiệu run khỏe: steps/s ổn định sau vài chục giây đầu (nếu tụt dần có thể RAM đang thiếu). avg score(20) có xu hướng tăng theo thời gian (dao động vài chục điểm giữa hai dòng là bình thường). entropy (PPO) giảm từ ≈ 2.2 xuống dần, không sụp đột ngột về gần 0. Q (DQN) tăng chậm và không phát nổ. Cách đọc chi tiết từng chỉ số: Vẽ biểu đồ, đọc log ."}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Xem agent chơi", "a": "visual", "x": "python -m pacman_rl train ppo --watch-every 500000 # mỗi 500k bước mở 1 ván Train tạm dừng trong lúc ván đó chạy (cần có màn hình). --render thì khác: nó mở cửa sổ ngay trên env đang train nhưng làm cả quá trình chậm hẳn, chỉ nên dùng để kiểm tra nhanh."}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Dừng giữa chừng và checkpoint", "a": "stop", "x": "Ctrl+C (hoặc nút Stop trong notebook) là cách dừng an toàn: hàm bắt KeyboardInterrupt , đóng các env, lưu .pt và trả về phần đã train . CLI sau đó vẫn lưu đủ 3 file. Checkpoint tự động chỉ có .pt : PPO mỗi save_every update (mặc định 200), DQN mỗi save_every bước env (mặc định 500,000). Cần có save_path . _episodes.npy và _log.npy chỉ được ghi khi hàm train kết thúc (kể cả khi Ctrl+C). Nếu máy sập hay process bị giết đột ngột, bạn chỉ còn .pt checkpoint gần nhất. Chạy rất dài? Đặt save_every nhỏ để mất ít nhất nếu máy treo. Với PPO mặc định, 200 update ≈ 410,000 bước."}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Train tiếp từ model có sẵn", "a": "resume", "x": "from pacman_rl import PPOConfig, train_ppo, load_run, get_device device = get_device() old = load_run(\"runs\", \"ppo\", \"ppo\", device) # TrainResult(model, log, episodes) cfg = PPOConfig(total_steps=1_000_000, lr=1e-4) # lr thấp hơn cho giai đoạn tinh chỉnh new = train_ppo(cfg, model=old.model, save_path=\"runs/ppo_cont.pt\", device=device) \"Train tiếp\" ở đây chỉ nạp trọng số Thư viện không lưu optimizer, bước hiện tại hay lịch learning rate. Vì vậy khi truyền model= : Optimizer (Adam) bắt đầu lại từ trạng thái trống. PPO : lịch lr chạy lại từ cfg.lr về 0 trong total_steps mới. Nên đặt lr thấp hơn "}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Chạy nhiều seed hoặc nhiều cấu hình", "a": "multi-run", "x": "Một lần chạy RL rất nhiễu: cùng cấu hình mà khác seed có thể khác nhau xa. Muốn kết luận \"cấu hình A tốt hơn B\", chạy mỗi cấu hình với ít nhất 3 seed ( --seed 0/1/2 ). for s in 0 1 2; do python -m pacman_rl train ppo --seed $s --name ppo_base_s$s python -m pacman_rl train ppo --seed $s --name ppo_c2_0.02_s$s --set c2=0.02 done foreach ($s in 0,1,2) { python -m pacman_rl train ppo --seed $s --name \"ppo_base_s$s\" python -m pacman_rl train ppo --seed $s --name \"ppo_c2_0.02_s$s\" --set c2=0.02 } from pacman_rl import PPOConfig, train_ppo, save_run, get_device def main(): device = get_device() for s"}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Chọn cỡ theo máy", "a": "sizing", "x": ""}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "n_envs và CPU", "a": "size-envs", "x": "Mặc định 16 phù hợp với CPU nhiều nhân. Máy yếu hơn: Máy Gợi ý 8 nhân trở lên, RAM 16 GB Giữ nguyên n_envs=16 4 đến 6 nhân --set n_envs=8 n_steps=256 (PPO giữ batch 2,048) Rất yếu hoặc kiểm tra nhanh --set n_envs=4 n_steps=512 . n_envs luôn phải chẵn. Đây là gợi ý theo nguyên tắc chung chứ không phải kết quả đo trên mọi máy. Cách tin cậy nhất là chạy ngắn và so steps/s ."}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Bộ nhớ", "a": "size-memory", "x": "Thành phần Công thức Mặc định Replay buffer DQN (RAM) buffer_size × 7,080 byte ≈ 1.4 GB (200,000) Rollout PPO (thiết bị tính toán) n_steps × n_envs × 28,224 byte ≈ 58 MB Process env n_envs process con 16 Muốn buffer lớn hơn (ví dụ 1,000,000 mẫu) thì cần khoảng 7 GB RAM trống, tính trước khi tăng buffer_size ."}, {"p": "guides/training.html", "t": "Setup và chạy huấn luyện", "h": "Thời gian dự kiến", "a": "size-time", "x": "Tốc độ thật phụ thuộc máy. Trên máy phát triển dự án (RTX 3070 Ti Laptop), PPO đo được khoảng 2,400 đến 3,400 steps/s và DQN khoảng 600 đến 1,900 steps/s (DQN dao động theo RAM trống). Suy ra: Run Bước Ước lượng (trên máy đó) PPO mặc định 2,000,000 khoảng 10 đến 14 phút DQN mặc định 10,000,000 khoảng 1.5 đến 4.5 giờ Hãy coi đây là bậc độ lớn để lên kế hoạch, và đo lại bằng một lần chạy ngắn trên máy của bạn."}, {"p": "index.html", "t": "pacman_rl", "h": "", "a": "", "x": "Tài liệu Thư viện huấn luyện PPO và DQN chơi Ms. Pacman (Atari) bằng PyTorch và Gymnasium. Một lệnh để train, một lệnh để chấm điểm, một lệnh để vẽ đường học, và đủ chỗ để bạn thêm thuật toán của riêng mình."}, {"p": "index.html", "t": "pacman_rl", "h": "pacman_rl làm được gì", "a": "what", "x": "Train hai thuật toán chuẩn : PPO (clipped objective + GAE) và DQN gốc (replay buffer + target network). Cả hai dùng chung một thân CNN kiểu Nature DQN. Chạy nhiều env song song : mặc định 16 env, mỗi env một process, chia 2 nhóm chạy xen kẽ với GPU. Chỉ có một policy; các env chỉ là nơi thu dữ liệu. Xem Env song song và pipeline . Chấm điểm công bằng : đánh giá luôn chạy game đầy đủ 3 mạng với seed cố định và cộng điểm thật, không phải reward đã biến đổi. Lưu và so sánh run : mỗi lần train ghi ra model, danh sách ván chơi và log; vẽ nhiều run lên cùng một biểu đồ bằng một lệnh. Dễ mở rộng : th"}, {"p": "index.html", "t": "pacman_rl", "h": "Bắt đầu từ đâu", "a": "start", "x": "Mới dùng Cài đặt Tạo môi trường, cài torch bản CUDA, cài pacman_rl và kiểm tra. Mới dùng Chạy thử trong 10 phút Train rất ngắn, chấm điểm, vẽ biểu đồ để chắc mọi thứ hoạt động. Huấn luyện Setup và chạy huấn luyện Cấu hình thật, theo dõi, dừng và train tiếp, chạy nhiều seed. Tham số PPOConfig / DQNConfig Từng tham số: ý nghĩa, công thức, tăng giảm thì sao, khi nào chỉnh. Hiểu thuật toán PPO và DQN trong code Từng bước của thuật toán gắn với đúng dòng code tương ứng. Đóng góp Thêm thuật toán mới Ví dụ chạy được: A2C trong khoảng 130 dòng, và Double DQN bằng một cờ trong config."}, {"p": "index.html", "t": "pacman_rl", "h": "Ví dụ nhanh nhất", "a": "example", "x": "python -m pacman_rl train ppo --steps 2000000 # lưu vào runs/ python -m pacman_rl eval ppo --episodes 10 # mean / std / max trên seed cố định python -m pacman_rl plot ppo --out curves.png # vẽ đường học from pacman_rl import PPOConfig, train_ppo, save_run, get_device device = get_device() result = train_ppo(PPOConfig(total_steps=2_000_000), save_path=\"ms_pacman_ppo.pt\", device=device) save_run(result, \".\", \"ms_pacman_ppo\") # .pt + _episodes.npy + _log.npy"}, {"p": "index.html", "t": "pacman_rl", "h": "Bản đồ tài liệu", "a": "map", "x": "Phần Trả lời câu hỏi Bắt đầu Cài thế nào? Chạy thử ra sao? Làm sao biết đã đúng? Khái niệm Env xử lý ảnh và điểm thế nào? Vì sao có nhiều env? PPO/DQN trong code làm gì từng bước? Hướng dẫn Làm việc X thì làm thế nào: train, chỉnh tham số, đánh giá, vẽ, thay reward. Tham chiếu Tra cứu: mọi tham số, mọi tùy chọn dòng lệnh, mọi hàm, mọi khóa trong log. Đóng góp Mã nguồn được tổ chức ra sao, và thêm thuật toán, chỉ số, reward, mạng thế nào cho đúng quy ước. Bấm tên hàm để mở code Khi mở docs bằng trình duyệt trực tiếp từ ổ đĩa ( file:// ), mọi tên hàm, lớp, hằng, tham số config và đường dẫn file "}, {"p": "reference/api.html", "t": "API Python", "h": "", "a": "", "x": "Tham chiếu Mọi hàm và lớp công khai, nhóm theo module. Phần lớn có thể import thẳng từ pacman_rl ; riêng biểu đồ nằm ở pacman_rl.plotting ."}, {"p": "reference/api.html", "t": "API Python", "h": "Cách import", "a": "imports", "x": "# nạp lười: `import pacman_rl` không kéo torch, chỉ khi dùng đến tên bên dưới mới nạp module chứa nó from pacman_rl import ( PPOConfig, piecewise_penalty, train_ppo, DQNConfig, train_dqn, TrainResult, # agents ActorCriticCNN, QNetwork, # models evaluate, watch, run_episodes, random_baseline, # evaluation ppo_policy, dqn_policy, save_run, load_run, load_runs, load_model, # runs get_device, describe_device, set_seed, moving_avg, # utils make_env, PipelinedEnvs, EpisodicLife, log_reward, count_events, ENV_ID, N_ACTIONS, # envs ) from pacman_rl.plotting import plot_training, plot_scores, plot_metr"}, {"p": "reference/api.html", "t": "API Python", "h": "pacman_rl.agents", "a": "agents", "x": ""}, {"p": "reference/api.html", "t": "API Python", "h": "train_ppo", "a": "train_ppo", "x": "train_ppo(cfg=None, *, model=None, save_path=None, device=None, render=False, watch_every=0, watch_episodes=1) -> TrainResult Train PPO. Tham số là PPOConfig (siêu tham số) và các tùy chọn chạy: model : ActorCriticCNN có sẵn để train tiếp; None thì tạo mới. save_path : file .pt lưu giữa chừng (mỗi save_every update) và lúc kết thúc. device : torch.device ; None thì get_device() . render : env số 0 mở cửa sổ, tất cả env chạy tuần tự. watch_every , watch_episodes : cứ mỗi watch_every bước env, mở cửa sổ cho agent chơi watch_episodes ván. Bắt KeyboardInterrupt : vẫn đóng env, lưu .pt và trả về ph"}, {"p": "reference/api.html", "t": "API Python", "h": "train_dqn", "a": "train_dqn", "x": "train_dqn(cfg=None, *, model=None, save_path=None, device=None, render=False, watch_every=0, watch_episodes=1) -> TrainResult Train DQN, tham số giống train_ppo (với DQNConfig và model là QNetwork ). Checkpoint lưu mỗi save_every bước env ."}, {"p": "reference/api.html", "t": "API Python", "h": "TrainResult", "a": "TrainResult", "x": "class TrainResult(NamedTuple): model: nn.Module # mạng đã train log: dict # tên chỉ số -> list, cùng độ dài với log[\"step\"] episodes: list # [(bước env, điểm thật của cả ván 3 mạng), ...] Unpack như tuple được: model, log, episodes = train_ppo(...) . Ý nghĩa các khóa trong log ở File lưu và log ."}, {"p": "reference/api.html", "t": "API Python", "h": "VecFrameReplayBuffer", "a": "VecFrameReplayBuffer", "x": "VecFrameReplayBuffer(capacity, n_envs, device=\"cpu\") .add(obs, action, reward, done, is_first) # mỗi tham số có độ dài n_envs; obs (n_envs,4,84,84) .sample(batch_size) -> (s, a, r, s2, done) # tensor trên device len(buffer) # số mẫu hiện có Replay buffer của DQN: lưu frame mới nhất mỗi bước, dựng lại chồng 4 frame khi rút mẫu. Giải thích ở DQN trong pacman_rl ."}, {"p": "reference/api.html", "t": "API Python", "h": "ALGOS", "a": "ALGOS", "x": "Dict {\"ppo\": (PPOConfig, train_ppo), \"dqn\": (DQNConfig, train_dqn)} . CLI tra cứu thuật toán qua đây; đăng ký thuật toán mới vào đây để dòng lệnh dùng được (xem Thêm thuật toán mới )."}, {"p": "reference/api.html", "t": "API Python", "h": "pacman_rl.models", "a": "models", "x": ""}, {"p": "reference/api.html", "t": "API Python", "h": "ActorCriticCNN", "a": "ActorCriticCNN", "x": "ActorCriticCNN(n_actions) .forward(x: uint8 (B,4,84,84)) -> (Categorical, value (B,)) .act(x) -> (action (B,), log_prob (B,), value (B,)) # @no_grad, lấy mẫu Gumbel-max Mạng của PPO: thân CNN kiểu Nature DQN dùng chung, đầu actor (logit) và đầu critic (giá trị)."}, {"p": "reference/api.html", "t": "API Python", "h": "QNetwork", "a": "QNetwork", "x": "QNetwork(n_actions) .forward(x: uint8 (B,4,84,84)) -> Q (B, n_actions) .head # nn.Linear(512, n_actions) Mạng của DQN: cùng thân CNN, đầu ra là giá trị Q cho từng action."}, {"p": "reference/api.html", "t": "API Python", "h": "make_cnn và MODEL_CLASSES", "a": "make_cnn", "x": "make_cnn() trả về thân CNN ( Conv32-8x8/4, Conv64-4x4/2, Conv64-3x3/1, Linear512 ), dùng chung cho cả hai mạng. MODEL_CLASSES = {\"ppo\": ActorCriticCNN, \"dqn\": QNetwork} dùng để nạp lại mạng đúng loại từ tên thuật toán."}, {"p": "reference/api.html", "t": "API Python", "h": "pacman_rl.envs", "a": "envs", "x": "Gói này không import torch (xem Kiến trúc )."}, {"p": "reference/api.html", "t": "API Python", "h": "make_env", "a": "make_env", "x": "make_env(render_mode=None, episodic_life=False, rgb_scale=False) -> gymnasium.Env obs_shape(rgb_scale=False) -> tuple # (4,84,84) hoặc (12,84,84) Tạo một env đã tiền xử lý (frame-skip 4, xám hoặc RGB, 84x84, noop reset tối đa 30, chồng 4 frame). rgb_scale=True trả quan sát RGB (12, 84, 84) (4 frame x 3 kênh gộp thành kênh). episodic_life=True chỉ dùng khi học. render_mode=\"human\" để mở cửa sổ."}, {"p": "reference/api.html", "t": "API Python", "h": "PipelinedEnvs", "a": "PipelinedEnvs", "x": "PipelinedEnvs(n_envs, n_groups=2, render=False, rgb_scale=False) .reset(seed=0) -> obs (n_envs,4,84,84), hoặc (n_envs,12,84,84) khi rgb_scale .send(g, actions) # gửi action cho nhóm g, trả về ngay (step_async) .recv(g) -> (obs, reward_thật, done, danh_sách_điểm_ván_vừa_kết_thúc, died) # died: float32 (gs,), 1.0 ở env vừa mất một mạng .close() # thuộc tính: G (số nhóm), gs (env mỗi nhóm), n (tổng env), slices, n_actions, envs Vector env cho việc học, chia thành n_groups nhóm để chạy xen kẽ với GPU. n_envs phải chia hết cho n_groups . Hai trình train hiện luôn dùng 2 nhóm. Xem Env song song và p"}, {"p": "reference/api.html", "t": "API Python", "h": "EpisodicLife", "a": "EpisodicLife", "x": "gym.Wrapper : mất mạng thì báo terminated=True ; chỉ reset game thật khi hết mạng; ghi info[\"life_lost\"] ( True ở bước vừa mất mạng) và info[\"game_score\"] khi hết cả ván."}, {"p": "reference/api.html", "t": "API Python", "h": "log_reward, count_events, pop_game_scores, pop_deaths", "a": "reward-helpers", "x": "log_reward(r) -> np.ndarray # log1p(r / 10), float32 count_events(reward) -> (n_pellet, n_ghost) pop_game_scores(infos) -> list[float] # điểm các ván vừa kết thúc hẳn, từ info của vector env pop_deaths(infos, n) -> np.ndarray # float32 (n,), 1.0 ở env vừa mất mạng (info[\"life_lost\"]) Hằng số: ENV_ID , N_ACTIONS (9), OBS_SHAPE ((4,84,84), mặc định xám; dùng obs_shape(rgb_scale) khi cần RGB), PELLET_REWARD (50), GHOST_REWARDS ((200,400,800,1600)). Ý nghĩa ở Môi trường và các loại điểm ."}, {"p": "reference/api.html", "t": "API Python", "h": "pacman_rl.evaluation", "a": "evaluation", "x": ""}, {"p": "reference/api.html", "t": "API Python", "h": "ppo_policy, dqn_policy, random_policy", "a": "ppo_policy", "x": "ppo_policy(model, device, greedy=False) -> act_fn # act_fn.rgb_scale suy ra từ số kênh của model dqn_policy(model, device, eps=0.05) -> act_fn random_policy(n_actions) -> act_fn ppo_policy : greedy=False lấy mẫu từ policy (giống lúc train); greedy=True luôn chọn action xác suất cao nhất. dqn_policy : epsilon-greedy với eps nhỏ để tránh kẹt."}, {"p": "reference/api.html", "t": "API Python", "h": "evaluate, watch, run_episodes, random_baseline", "a": "evaluate", "x": "evaluate(act_fn, n_episodes=10, max_steps=4500, seed=1000) -> list[float] watch(act_fn, episodes=2, max_steps=4500) -> list[float] # mở cửa sổ run_episodes(act_fn, n_episodes=10, max_steps=4500, seed=None, render_mode=None, verbose=False, rgb_scale=None) -> list[float] # rgb_scale=None: theo act_fn random_baseline(n_episodes=5, n_actions=9) -> list[float] Tất cả chạy game đầy đủ 3 mạng và trả về danh sách điểm thật mỗi ván. seed=None : mỗi ván ngẫu nhiên. seed=k : ván thứ i dùng seed k + i . max_steps giới hạn số bước (action) mỗi ván; ván bị cắt vẫn tính điểm đã có. random_baseline không giới"}, {"p": "reference/api.html", "t": "API Python", "h": "pacman_rl.runs", "a": "runs", "x": "save_run(result, directory, name, append=True) -> (path_model, path_episodes, path_log) load_run(directory, name, algo, device=\"cpu\") -> TrainResult load_model(path, algo, device=\"cpu\", n_actions=N_ACTIONS) -> nn.Module # chế độ eval; số kênh (4/12) đọc từ checkpoint load_runs(directory, names=None, algo=None, device=\"cpu\") -> dict[tên, TrainResult] list_runs(directory) -> list[str] # tên mọi run (file .pt) trong thư mục, sắp theo tên run_paths(directory, name) -> (path_model, path_episodes, path_log) save_run với append=True (mặc định): nếu run name đã có trong directory thì episodes và log c"}, {"p": "reference/api.html", "t": "API Python", "h": "pacman_rl.plotting", "a": "plotting", "x": "Mọi hàm nhận runs : dict tên → TrainResult (hoặc tuple (model, log, episodes) ), nên vẽ một hay nhiều run đều cùng một cách. Nhiều hàm nhận ax= / axes= để ghép vào figure của bạn. plot_training(runs, random_scores=None, save_path=None, show=True, bin_size=100_000) -> Figure # 6 biểu đồ tổng hợp (lưới 2x3) plot_scores(runs, random_scores=None, w=20, ax=None, scatter=None) # trung bình trượt w ván; scatter=None: chấm điểm thô chỉ khi dưới 4 run plot_ranking(runs, last=50, ax=None) # thanh ngang xếp hạng run theo điểm TB last ván cuối (kèm std) compare(names=None, directory=\"runs\", random_scores="}, {"p": "reference/api.html", "t": "API Python", "h": "pacman_rl.utils", "a": "utils", "x": "get_device(prefer_cuda=True) -> torch.device # cuda nếu có; bật TF32 và cuDNN benchmark describe_device(device) -> str # \"cuda | tên GPU\" hoặc \"cpu | CPU\" set_seed(seed) # random, numpy, torch moving_avg(x, w) -> np.ndarray # trung bình trượt, chế độ \"valid\""}, {"p": "reference/cli.html", "t": "Dòng lệnh (CLI)", "h": "", "a": "", "x": "Tham chiếu Bốn lệnh con: train , eval , play , plot . Chạy được ở thư mục bất kỳ khi môi trường đang bật. python -m pacman_rl <lệnh> [tùy chọn] pacman-rl <lệnh> [tùy chọn] # tương đương python -m pacman_rl <lệnh> -h # xem đủ tùy chọn của một lệnh Quy ước chung: algo là ppo hoặc dqn . Thư mục mặc định cho mọi file là runs/ của thư mục hiện tại. Tên run mặc định là ms_pacman_<algo> ."}, {"p": "reference/cli.html", "t": "Dòng lệnh (CLI)", "h": "train", "a": "train", "x": "python -m pacman_rl train <algo> [--steps N] [--seed S] [--out DIR] [--name NAME] [--set KEY=VALUE ...] [--render] [--watch-every N] Tùy chọn Mặc định Ý nghĩa algo bắt buộc ppo hoặc dqn --steps N theo config Tổng số bước env. Đè lên total_steps kể cả khi --set total_steps=... cũng có mặt. --seed S 0 Seed. Luôn đè lên --set seed=... . --out DIR runs Thư mục lưu kết quả (tự tạo nếu chưa có). --name NAME ms_pacman_<algo> Tên run; quyết định tên 3 file lưu. Trùng tên là ghi đè. --set KEY=VALUE ... - Ghi đè siêu tham số, có thể nhiều cặp cách nhau bằng dấu cách. --render tắt Mở cửa sổ game ở env số"}, {"p": "reference/cli.html", "t": "Dòng lệnh (CLI)", "h": "Cú pháp --set", "a": "set", "x": "Mỗi cặp dạng tên=giá trị , không có dấu cách quanh dấu = . Giá trị được ép kiểu theo kiểu của tham số: trường int nhận cả dạng khoa học ( total_steps=2e6 , buffer_size=5e5 ); trường float nhận 1e-4 , 0.02 . Tên không tồn tại sẽ dừng với thông báo liệt kê các tham số hợp lệ. reward_fn không đặt được từ CLI. Các tham số hợp lệ: xem PPOConfig và DQNConfig . Hai bộ khác nhau, tham số của DQN không dùng được cho PPO và ngược lại."}, {"p": "reference/cli.html", "t": "Dòng lệnh (CLI)", "h": "Ví dụ", "a": "train-examples", "x": "python -m pacman_rl train ppo --steps 2000000 python -m pacman_rl train dqn --steps 10000000 --seed 1 --name dqn_seed1 python -m pacman_rl train ppo --set lr=1e-4 n_envs=8 n_steps=256 c2=0.02 python -m pacman_rl train ppo --watch-every 500000 Đầu ra: dòng device: ... | config: {...} (in ra toàn bộ cấu hình thực tế), các dòng log, rồi đường dẫn ba file đã lưu."}, {"p": "reference/cli.html", "t": "Dòng lệnh (CLI)", "h": "eval", "a": "eval", "x": "Chấm điểm một model đã lưu trên các ván đầy đủ 3 mạng, không mở cửa sổ. python -m pacman_rl eval <algo> [--dir DIR] [--name NAME] [--episodes N] [--seed S] [--greedy] [--eps E] Tùy chọn Mặc định Ý nghĩa --dir DIR runs Thư mục chứa run. --name NAME ms_pacman_<algo> Tên run cần nạp (file NAME.pt ). --episodes N 10 Số ván chấm điểm. --seed S 1000 Ván thứ i dùng seed S + i . --greedy tắt Chỉ PPO. Chọn action có xác suất cao nhất thay vì lấy mẫu. --eps E 0.05 Chỉ DQN. Epsilon khi chơi. PPO trên 3 ván: mean 453 | std 191 | max 720 Điểm: [280, 360, 720]"}, {"p": "reference/cli.html", "t": "Dòng lệnh (CLI)", "h": "play", "a": "play", "x": "Mở cửa sổ game để xem model chơi (cần màn hình). Tùy chọn giống eval trừ --seed (không có) và --episodes mặc định 2. python -m pacman_rl play ppo --greedy --episodes 3 python -m pacman_rl play dqn --name dqn_seed1 --eps 0.01"}, {"p": "reference/cli.html", "t": "Dòng lệnh (CLI)", "h": "plot", "a": "plot", "x": "Vẽ đường học từ các run đã lưu ra file PNG (không mở cửa sổ). python -m pacman_rl plot <ALGO[:NAME]> ... [--dir DIR] [--out FILE] Tùy chọn Mặc định Ý nghĩa ALGO[:NAME] bắt buộc, một hoặc nhiều ppo hoặc ppo:ten_run . ALGO cho biết loại mạng khi nạp; NAME là tên run (bỏ qua thì dùng ms_pacman_<algo> ). --dir DIR runs Thư mục chứa các run (dùng chung cho mọi run trong lệnh). --out FILE curves.png File ảnh đầu ra. Nhãn trong biểu đồ là NAME nếu có, không thì PPO / DQN . Màu cố định chỉ áp dụng cho nhãn PPO / DQN (xanh dương, cam); nhãn khác lấy màu theo thứ tự. python -m pacman_rl plot ppo dqn --o"}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "", "a": "", "x": "Tham chiếu Mọi siêu tham số của train_dqn . Khác với PPO, DQN tính phần lớn các mốc (log, lưu, cập nhật target) theo bước env , và có thêm nhóm tham số của replay buffer và epsilon. from pacman_rl import DQNConfig cfg = DQNConfig(total_steps=10_000_000, buffer_size=200_000, lr=1e-4) Cột \"Tăng / Giảm\" là xu hướng chung trong RL, chưa được kiểm chứng riêng trên dự án này; hãy xác nhận bằng nhiều seed. Thuật toán được giải thích ở DQN trong pacman_rl ."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Bảng tóm tắt", "a": "summary", "x": "Tham số Mặc định Đơn vị Một dòng total_steps 10,000,000 bước env Tổng số bước n_envs 16 env Số env song song (mẫu mới mỗi vòng) buffer_size 200,000 mẫu Dung lượng replay buffer batch_size 128 mẫu Cỡ minibatch mỗi lần học updates_per_iter 1 lần / vòng Số lần học mỗi vòng thu lr 1e-4 - Learning rate của Adam (cố định) gamma 0.99 - Hệ số chiết khấu learning_starts 20,000 bước env Thu thập bao nhiêu trước khi học target_update 10,000 bước env Chu kỳ sao chép sang target network eps_start 1.0 - Epsilon ban đầu eps_end 0.05 - Epsilon thấp nhất eps_frac 0.05 tỷ lệ Phần đầu của run dùng để giảm epsilo"}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Đại lượng dẫn xuất", "a": "derived", "x": "Đại lượng Công thức Mặc định Số vòng lặp n_iters total_steps // n_envs 625,000 Tỷ lệ tái sử dụng (replay ratio) updates_per_iter × batch_size / n_envs 8 Bước epsilon giảm int(eps_frac × total_steps) 500,000 Số bước mỗi cột của buffer buffer_size // n_envs 12,500 Bộ nhớ buffer buffer_size × 7,080 byte ≈ 1.4 GB"}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Quy mô chạy", "a": "scale", "x": ""}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "total_steps int mặc định 10,000,000", "a": "total_steps", "x": "Tổng số bước env cho cả lần train (1 bước = 1 action = 4 frame). Số vòng lặp là total_steps // n_envs , phần dư bị bỏ. Điều khiển Độ dài run và độ dài đoạn giảm epsilon (vì eps_frac là tỷ lệ của tổng này). Tăng Nhiều thời gian học hơn; epsilon giảm chậm hơn theo số bước tuyệt đối. Giảm Chạy nhanh để thử. Epsilon cũng giảm nhanh hơn theo số bước tuyệt đối vì đoạn giảm co lại theo tổng. Khi nào chỉnh Mọi lần. Để tham khảo, DQN gốc (Nature 2015) train 50 triệu frame, tức khoảng 12.5 triệu bước."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "n_envs int mặc định 16", "a": "n_envs", "x": "Số env song song; mỗi vòng lặp thu đúng n_envs chuyển tiếp mới (một từ mỗi env). Phải chẵn. Xem Env song song và pipeline . Điều khiển Tốc độ thu dữ liệu, và cùng với batch_size , updates_per_iter quyết định tỷ lệ tái sử dụng. Tăng Thu nhanh hơn, buffer đa dạng hơn; tỷ lệ tái sử dụng giảm nếu giữ nguyên batch_size và updates_per_iter (mỗi mẫu được học lại ít lần hơn). Giảm Nhẹ máy, tỷ lệ tái sử dụng tăng, nhưng thu chậm. Khi nào chỉnh Theo số nhân CPU và RAM. Đổi n_envs thì xem lại replay ratio ."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Replay buffer và minibatch", "a": "buffer", "x": ""}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "buffer_size int mặc định 200,000", "a": "buffer_size", "x": "Số chuyển tiếp tối đa buffer giữ. Đầy thì ghi đè mẫu cũ nhất. Mỗi mẫu tốn khoảng 7,080 byte RAM. Điều khiển Độ \"dài trí nhớ\" của agent và độ đa dạng của dữ liệu học. Tăng Giảm tương quan giữa các mẫu, giữ được trải nghiệm hiếm lâu hơn. Tốn RAM tuyến tính: 1,000,000 mẫu ≈ 7 GB. Mẫu cũ có thể lỗi thời so với policy hiện tại. Giảm Tiết kiệm RAM, dữ liệu mới hơn nhưng ít đa dạng; dễ bất ổn hơn. Khi nào chỉnh Khi RAM không đủ (giảm) hoặc khi có nhiều RAM trống (tăng). Nên chia hết cho n_envs . Phải lớn hơn learning_starts ."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "batch_size int mặc định 128", "a": "batch_size", "x": "Số mẫu rút từ buffer cho mỗi lần tính gradient. Điều khiển Độ nhiễu của gradient và (cùng với updates_per_iter , n_envs ) tỷ lệ tái sử dụng. Tăng Gradient mượt hơn, nhưng mỗi bước học tốn thời gian hơn; tăng tỷ lệ tái sử dụng. Giảm Nhanh hơn mỗi bước, gradient nhiễu hơn, giảm tỷ lệ tái sử dụng. Khi nào chỉnh Mặc định 128 được chọn để cho tỷ lệ tái sử dụng 8 với 16 env. Đổi n_envs thì đổi batch_size theo tỷ lệ để giữ 8."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "updates_per_iter int mặc định 1", "a": "updates_per_iter", "x": "Số lần tính gradient (mỗi lần một minibatch batch_size ) trong mỗi vòng lặp, sau khi đã thu n_envs mẫu. Điều khiển Cân bằng giữa \"thu thêm\" và \"học lại\". Là cách khác để đổi tỷ lệ tái sử dụng mà không đổi cỡ minibatch. Tăng Học nhiều hơn trên cùng lượng dữ liệu (mẫu hiệu quả hơn) nhưng chậm hơn và có nguy cơ bất ổn. Giảm Không thể thấp hơn 1 nếu muốn học (0 nghĩa là không học). Khi nào chỉnh Khi muốn tăng tốc độ học theo bước env, đổi đây thay vì batch_size để giữ minibatch cố định."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Tối ưu hóa và mục tiêu", "a": "optim", "x": ""}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "lr float mặc định 1e-4", "a": "lr", "x": "Learning rate của Adam. Cố định suốt run (không có lịch giảm như PPO). Tăng Học nhanh hơn, dễ bất ổn: loss nhảy, q_mean phát nổ. Giảm Ổn định hơn nhưng chậm. Khi nào chỉnh Khi q_mean tăng vô độ hoặc loss không ổn định, thử giảm."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "gamma float mặc định 0.99", "a": "gamma", "x": "Hệ số chiết khấu trong mục tiêu Bellman y = r + γ(1 − done)·max Q_target(s') . Chân trời hiệu dụng khoảng 1/(1 − γ) ≈ 100 bước. Tăng Nhìn xa hơn nhưng Q lớn hơn và khó ổn định. Giảm Thiển cận hơn, dễ học hơn. Khi nào chỉnh Hiếm. 0.99 là chuẩn."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "max_grad float mặc định 10.0", "a": "max_grad", "x": "Ngưỡng cắt chuẩn gradient trước optimizer.step() . Cao hơn PPO (0.5) vì loss Huber đã giới hạn gradient theo mẫu. Khi nào chỉnh Hiếm. Hạ xuống nếu loss có những cú nhảy lớn đột ngột."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Lịch học và target network", "a": "schedule", "x": ""}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "learning_starts int mặc định 20,000", "a": "learning_starts", "x": "Số bước env chỉ thu thập (chưa học) ở đầu run, để buffer có đủ mẫu trước khi rút minibatch. Điều khiển Mạng không học trên một buffer gần như trống và lặp đi lặp lại vài mẫu giống nhau. Tăng Buffer đa dạng hơn lúc bắt đầu, học khởi động muộn hơn. Giảm Học sớm nhưng trên dữ liệu ít ỏi. Không nên đặt thấp hơn vài trăm: buffer cần ít nhất vài bước thời gian mới rút mẫu được. Khi nào chỉnh Run thử ngắn thì giảm cho tương xứng (ví dụ 500 với run vài nghìn bước). Phải nhỏ hơn buffer_size ."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "target_update int mặc định 10,000", "a": "target_update", "x": "Cứ mỗi bấy nhiêu bước env, sao chép trọng số mạng chính sang target network (cập nhật \"cứng\"). Điều khiển Độ \"đứng yên\" của mục tiêu học. Mục tiêu đổi liên tục dễ làm Q dao động hoặc phân kỳ. Tăng Mục tiêu ổn định hơn nhưng phản ánh tiến bộ chậm hơn. Giảm Mục tiêu bám sát mạng hiện tại, học nhanh hơn nhưng kém ổn định. Khi nào chỉnh Nếu q_mean phát nổ hoặc loss dao động mạnh thì thử tăng."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Khám phá (epsilon-greedy)", "a": "epsilon", "x": "Epsilon giảm tuyến tính từ eps_start xuống eps_end trong eps_frac × total_steps bước đầu, rồi giữ ở eps_end . Ba tham số sau cùng định hình đường cong này."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "eps_start float mặc định 1.0", "a": "eps_start", "x": "Xác suất chọn action ngẫu nhiên lúc bắt đầu. 1.0 nghĩa là hoàn toàn ngẫu nhiên. Khi nào chỉnh Khi train tiếp từ model đã học ( model=... ): đặt thấp (như 0.1), nếu không agent bị ép chơi ngẫu nhiên lại từ đầu."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "eps_end float mặc định 0.05", "a": "eps_end", "x": "Xác suất ngẫu nhiên tối thiểu, giữ đến hết run. Tăng Khám phá mãi nhiều hơn; điểm lúc train bị kéo xuống vì một phần ε số action vẫn là ngẫu nhiên. Giảm Khai thác nhiều hơn nhưng có thể kẹt trong thói quen."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "eps_frac float mặc định 0.05", "a": "eps_frac", "x": "Phần trăm (dạng tỷ lệ) của total_steps dùng để giảm epsilon. Mặc định 5% của 10 triệu = 500,000 bước. Tăng Khám phá ngẫu nhiên kéo dài hơn. Giảm Chuyển sang khai thác sớm hơn. Khi nào chỉnh Nhớ rằng đoạn giảm tính theo tỷ lệ của total_steps : đổi total_steps thì đoạn giảm cũng đổi theo."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Tái lập, ghi log, lưu", "a": "infra", "x": ""}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "seed int mặc định 0", "a": "seed", "x": "Seed cho random , numpy , torch và các env (env thứ k dùng seed + k ). Trên CLI dùng --seed ."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "log_every int mặc định 100,000", "a": "log_every", "x": "Ghi một điểm vào log và in một dòng mỗi bấy nhiêu bước env . Các chỉ số loss , q_mean là trung bình từ lần ghi trước. Lưu ý Khác PPO, ở DQN log_every quyết định luôn số điểm của đường cong. Nếu total_steps < log_every thì log rỗng (không có điểm nào). Với run thử ngắn hãy đặt log_every nhỏ."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "save_every int mặc định 500,000", "a": "save_every", "x": "Lưu checkpoint .pt (trọng số mạng chính) mỗi bấy nhiêu bước env khi có save_path ."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "reward_fn Callable mặc định log_reward", "a": "reward_fn", "x": "Hàm nhận mảng reward thật của một nhóm env và trả về reward học, giống PPO. Không đặt được từ CLI. Xem Reward shaping ."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "death_penalty float mặc định 0.0", "a": "death_penalty", "x": "Số điểm trừ khỏi reward học ở bước agent vừa mất một mạng: reward_học = reward_fn(reward) - death_penalty * died . Mặc định 0 là không phạt. Điều khiển Chỉ reward học (cùng thang với reward_fn : chấm nhỏ ≈ 0.69, viên năng lượng ≈ 1.79). Điểm báo cáo, số viên năng lượng và số ma vẫn tính từ reward thật. Khi nào chỉnh Khi agent hay lao vào ma. Giá trị thử: 1 đến 3. Phạt quá lớn khiến agent né ma quá mức và đứng yên."}, {"p": "reference/dqn-config.html", "t": "DQNConfig", "h": "Những thứ cố định, không phải tham số", "a": "fixed", "x": "Hàm loss : Huber ( smooth_l1_loss ), không phải MSE. Cập nhật target : sao chép cứng định kỳ, không phải trung bình trượt (Polyak). Mục tiêu : max của target network, không phải Double DQN. Optimizer : Adam với tham số mặc định của PyTorch (ngoài lr )."}, {"p": "reference/files-and-logs.html", "t": "File lưu và log", "h": "", "a": "", "x": "Tham chiếu Một lần train ghi ra ba file. Trang này mô tả định dạng từng file, từng khóa trong log , và các đơn vị khác nhau giữa PPO và DQN."}, {"p": "reference/files-and-logs.html", "t": "File lưu và log", "h": "Một run gồm ba file", "a": "files", "x": "Run tên NAME trong thư mục DIR : File Nội dung Ghi lúc nào NAME.pt state_dict của mạng (PyTorch) Giữa chừng (checkpoint) và khi kết thúc NAME_episodes.npy Mảng (N, 2) : mỗi hàng là (bước env, điểm thật cả ván) cho một ván đã kết thúc Khi kết thúc (qua save_run ) NAME_log.npy Dict các chỉ số theo thời gian (lưu bằng pickle) Khi kết thúc (qua save_run ) Gọi save_run vào một NAME đã tồn tại sẽ nối _episodes.npy và _log.npy vào sau dữ liệu cũ (bước env tiếp nối, nên vẽ biểu đồ liền mạch), còn .pt được ghi đè. Truyền append=False để ghi đè hoàn toàn. Định dạng này trùng với notebook cũ ( ms_pacman_"}, {"p": "reference/files-and-logs.html", "t": "File lưu và log", "h": "Đọc run trong Python", "a": "read-python", "x": "import numpy as np from pacman_rl import load_run result = load_run(\"runs\", \"ms_pacman_ppo\", \"ppo\") # TrainResult(model, log, episodes) model, log, episodes = result steps = np.array(log[\"step\"]) entropy = np.array(log[\"ent\"]) games = np.array(episodes) # (N, 2): cột 0 là bước, cột 1 là điểm print(\"Số ván:\", len(games), \"| điểm 20 ván cuối:\", games[-20:, 1].mean()) Chỉ nạp file từ nguồn tin cậy _log.npy được nạp với allow_pickle=True và .pt dùng torch.load ; cả hai có thể thực thi mã tùy ý nếu file bị cài độc. Đừng nạp run lấy từ người lạ."}, {"p": "reference/files-and-logs.html", "t": "File lưu và log", "h": "Những gì không được lưu", "a": "not-saved", "x": "Cấu hình (siêu tham số) không nằm trong file nào. CLI in config ở dòng đầu khi train; hãy ghi lại, ví dụ python -m pacman_rl train ppo ... | tee ppo_s0.txt hoặc đặt tên run mô tả được cấu hình ( ppo_c2_0.02_s0 ). Optimizer, bước hiện tại, lịch lr, replay buffer không được lưu. Vì vậy chưa thể \"resume\" chính xác; xem Train tiếp từ model có sẵn ."}, {"p": "reference/files-and-logs.html", "t": "File lưu và log", "h": "Đơn vị: update hay bước env?", "a": "units", "x": "PPO và DQN đếm tiến độ khác nhau. Đây là nguồn nhầm lẫn thường gặp nhất: PPO DQN log_every update (mặc định 50 ≈ 102,400 bước) bước env (mặc định 100,000) save_every update (mặc định 200 ≈ 409,600 bước) bước env (mặc định 500,000) Chỉ số vào log Mỗi update (không phụ thuộc log_every ) Mỗi log_every bước env Số điểm trong log (mặc định) 976 100 Trong log và episodes , trục \"step\" luôn là bước env ở cả hai thuật toán, nên vẽ chung được."}, {"p": "reference/files-and-logs.html", "t": "File lưu và log", "h": "Các khóa trong log", "a": "log-keys", "x": "log là dict, mỗi khóa là một list, mọi list cùng độ dài với log[\"step\"] . Khóa PPO DQN Ý nghĩa step có có Bước env tại thời điểm ghi. pellets có có Tổng tích lũy số viên năng lượng đã ăn (từ đầu run). ghosts có có Tổng tích lũy số ma đã ăn. deaths có có Tổng tích lũy số mạng đã mất. death_penalty có - Phạt mất mạng đang dùng ở update đó (đổi theo penalty_schedule nếu có). Run cũ không có khóa này. step_penalty có - Phạt mỗi bước đang dùng ở update đó. Run cũ không có khóa này. ent có - Entropy trung bình của policy (minibatch cuối của update). kl có - Xấp xỉ KL giữa policy cũ và mới: mean(logp"}, {"p": "reference/files-and-logs.html", "t": "File lưu và log", "h": "episodes", "a": "episodes", "x": "Danh sách (bước env, điểm) cho mỗi ván hoàn chỉnh (đủ 3 mạng) đã kết thúc trong lúc train. \"Bước env\" là bước toàn cục lúc ván kết thúc. Điểm là điểm thật (không biến đổi). Mất mạng giữa chừng không tạo ra mục mới. avg score(20) trong dòng log chính là trung bình của 20 mục cuối của danh sách này."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "", "a": "", "x": "Tham chiếu Mọi siêu tham số của train_ppo : mỗi tham số cho biết nó là gì, đơn vị, nó điều khiển phần nào của thuật toán, tăng hay giảm thì có xu hướng gì, và khi nào nên chỉnh. from pacman_rl import PPOConfig cfg = PPOConfig(total_steps=2_000_000, n_envs=16, lr=2.5e-4) # chỉ ghi các trường muốn đổi Các cột \"Tăng / Giảm\" mô tả xu hướng chung trong RL, không phải kết quả đo riêng trên dự án này. Hãy xác nhận bằng nhiều seed (xem Chạy nhiều seed ). Thuật toán được giải thích ở PPO trong pacman_rl ."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "Bảng tóm tắt", "a": "summary", "x": "Tham số Mặc định Nhóm Một dòng total_steps 2,000,000 Quy mô Tổng số bước env n_envs 16 Quy mô Số env song song n_steps 128 Rollout Bước mỗi env trong một rollout epochs 4 Cập nhật Số lần quét mỗi rollout n_minibatches 4 Cập nhật Số minibatch mỗi lần quét lr 2.5e-4 Tối ưu Learning rate ban đầu (giảm về 0) gamma 0.99 Advantage Hệ số chiết khấu lam 0.95 Advantage λ của GAE clip_eps 0.1 Loss Ngưỡng cắt tỷ lệ policy c1 0.5 Loss Trọng số value loss c2 0.01 Loss Trọng số entropy bonus max_grad 0.5 Tối ưu Cắt chuẩn gradient seed 0 Tái lập Seed ngẫu nhiên log_every 50 Ghi/lưu In log mỗi N update save_e"}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "Đại lượng dẫn xuất", "a": "derived", "x": "Vài con số không phải tham số nhưng quyết định hành vi, được suy ra từ các tham số trên: Đại lượng Công thức Mặc định batch n_envs × n_steps 2,048 minibatch batch // n_minibatches 512 n_updates total_steps // batch 976 Gradient step mỗi update epochs × n_minibatches 16 Chân trời hiệu dụng của gamma 1 / (1 − gamma) ≈ 100 bước"}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "Quy mô chạy", "a": "scale", "x": ""}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "total_steps int mặc định 2,000,000", "a": "total_steps", "x": "Tổng số bước env cho cả lần train. Một bước là một action, tương ứng 4 frame; 2,000,000 bước là 8,000,000 frame. Điều khiển Độ dài run, và độ dài lịch giảm learning rate (lr về 0 đúng lúc kết thúc). Làm tròn Số update là total_steps // batch , phần dư bị bỏ. Với mặc định chỉ chạy 976 update = 1,998,848 bước. Tăng Agent có thêm thời gian học, lịch lr dài hơn. Chi phí tăng tuyến tính. Giảm Chạy nhanh để thử, nhưng agent chưa kịp học. Run dưới vài chục nghìn bước chỉ để kiểm tra pipeline. Khi nào chỉnh Gần như mọi lần. Thử nhanh dùng 50,000 đến 200,000; kết quả báo cáo nên dùng từ vài triệu trở l"}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "n_envs int mặc định 16", "a": "n_envs", "x": "Số env chạy song song, mỗi env một process. Chỉ có một policy; các env chỉ thu dữ liệu. Xem Env song song và pipeline . Điều khiển Tốc độ thu dữ liệu, độ đa dạng của batch, và kích thước batch ( n_envs × n_steps ). Ràng buộc Phải chẵn (chia 2 nhóm cho pipeline). Nên để n_envs × n_steps chia hết cho n_minibatches , nếu không minibatch cuối sẽ nhỏ hơn. Tăng Thu nhanh hơn nếu còn nhân CPU rảnh; batch to hơn và đa dạng hơn; ít update hơn trên cùng total_steps . Quá số nhân CPU thì không nhanh thêm. Giảm Nhẹ máy hơn nhưng chậm hơn. Batch nhỏ lại nếu không bù bằng n_steps . Khi nào chỉnh Khi máy ít "}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "Rollout và cập nhật", "a": "rollout", "x": ""}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "n_steps int mặc định 128", "a": "n_steps", "x": "Số bước mỗi env đi trước khi dừng lại để học. Cùng với n_envs tạo thành một rollout. Điều khiển Độ dài đoạn mà GAE nhìn trước, và tần suất cập nhật policy. Cuối rollout, giá trị tương lai được ước bằng critic ( last_value ). Tăng Mỗi update dùng nhiều dữ liệu hơn từ cùng một policy, advantage dựa nhiều vào thực tế hơn là ước lượng của critic; nhưng policy được cập nhật thưa hơn. Giảm Cập nhật dày hơn nhưng batch nhỏ hơn và advantage phụ thuộc critic nhiều hơn. Khi nào chỉnh Thường chỉ chỉnh để bù khi đổi n_envs . Giá trị 128 là chuẩn cho Atari."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "epochs int mặc định 4", "a": "epochs", "x": "Số lần quét qua toàn bộ rollout trong mỗi update (mỗi lần quét xáo trộn lại thứ tự mẫu). Điều khiển Mỗi mẫu dữ liệu on-policy được dùng lại bao nhiêu lần. Đây cũng là đòn bẩy chính quyết định policy đi xa bao nhiêu trong một update. Tăng Khai thác dữ liệu nhiều hơn (ít tốn công thu hơn) nhưng policy lệch xa lúc thu dữ liệu: kl và clipfrac tăng. Quá nhiều có thể làm học bất ổn. Giảm An toàn hơn nhưng cần nhiều dữ liệu hơn để học cùng một lượng. Khi nào chỉnh Khi clipfrac thường xuyên cao (> 0.3) thì giảm; khi quá thấp và học chậm thì có thể tăng."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "n_minibatches int mặc định 4", "a": "n_minibatches", "x": "Mỗi lần quét chia batch thành bấy nhiêu minibatch, mỗi minibatch tính một lần gradient. Điều khiển Kích thước minibatch ( batch // n_minibatches = 512) và số lần cập nhật trọng số mỗi update ( epochs × n_minibatches = 16). Tăng Minibatch nhỏ hơn, nhiều bước cập nhật hơn, gradient nhiễu hơn. Giảm Minibatch lớn hơn, gradient mượt hơn, ít bước hơn (và tốn nhiều bộ nhớ GPU hơn mỗi bước). Khi nào chỉnh Hiếm khi. Nếu GPU hết bộ nhớ khi học, tăng n_minibatches ."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "Tối ưu hóa", "a": "optim", "x": ""}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "lr float mặc định 2.5e-4", "a": "lr", "x": "Learning rate của Adam ở đầu run . Giảm tuyến tính về 0 theo công thức lr × (1 − update / n_updates) . Điều khiển Bước nhảy của mỗi lần cập nhật. Tham số nhạy nhất của PPO. Tăng Học nhanh hơn lúc đầu nhưng dễ bất ổn: KL và clipfrac cao, điểm đột ngột sụp. Giảm Ổn định hơn nhưng chậm; entropy đứng yên gần 2.197 trong thời gian dài là dấu hiệu học quá chậm. Khi nào chỉnh Là thứ đầu tiên thử khi đường học bất thường. Khi train tiếp từ model có sẵn nên đặt thấp hơn lần đầu (lịch lr chạy lại từ đầu)."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "max_grad float mặc định 0.5", "a": "max_grad", "x": "Ngưỡng cắt chuẩn gradient ( clip_grad_norm_ ) trước mỗi lần optimizer.step() . Gradient có chuẩn lớn hơn ngưỡng sẽ bị co lại cho vừa. Điều khiển Chặn những lần cập nhật \"đột biến\" do một minibatch bất thường. Tăng Ít can thiệp hơn; nguy cơ một vài bước lớn phá policy. Giảm Mọi bước bị kìm nhỏ lại, học chậm hơn. Khi nào chỉnh Hiếm. Giữ 0.5 trừ khi bạn có lý do cụ thể."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "Advantage và chiết khấu", "a": "advantage", "x": ""}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "gamma float mặc định 0.99", "a": "gamma", "x": "Hệ số chiết khấu γ: reward nhận sau k bước chỉ được tính γ^k . Điều khiển Agent coi trọng tương lai bao xa. Chân trời hiệu dụng khoảng 1 / (1 − γ) bước; ở 0.99 là cỡ 100 bước (400 frame, khoảng 7 giây game). Tăng Nhìn xa hơn (hợp với việc tránh ma, lên kế hoạch ăn viên năng lượng) nhưng giá trị khó ước lượng, phương sai cao. Giảm Thiển cận, chỉ chăm chấm gần; học dễ hơn nhưng hành vi kém chiến lược. Khi nào chỉnh Hiếm. 0.99 là chuẩn cho Atari."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "lam float mặc định 0.95", "a": "lam", "x": "Tham số λ của GAE, pha trộn giữa ước lượng \"một bước\" và \"đến hết rollout\" khi tính advantage. Điều khiển Đánh đổi bias và variance của advantage. lam=0 : chỉ nhìn một bước và tin vào critic (bias cao, variance thấp). lam=1 : dùng reward thực tế đến hết rollout (bias thấp, variance cao). Tăng Ít phụ thuộc vào critic nhưng nhiễu hơn. Giảm Mượt hơn nhưng thiên lệch nếu critic còn kém. Khi nào chỉnh Hiếm. 0.95 là chuẩn."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "Hàm loss", "a": "loss", "x": ""}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "clip_eps float mặc định 0.1", "a": "clip_eps", "x": "Ngưỡng ε của clipped objective: tỷ lệ π_new / π_old bị cắt trong [1 − ε, 1 + ε] . Điều khiển Một update được phép đẩy xác suất của một action đi xa bao nhiêu. Là \"hàng rào an toàn\" của PPO. Tăng Cho phép bước lớn hơn, học nhanh hơn nhưng kém ổn định. Giảm Bảo thủ hơn; clipfrac (tỷ lệ mẫu bị cắt) tăng vì dễ chạm ngưỡng hơn. Khi nào chỉnh Thường chỉnh cùng lr và epochs khi đường học bất ổn. Mặc định 0.1 là giá trị cho Atari; giữ nguyên suốt run (không giảm dần)."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "c1 float mặc định 0.5", "a": "c1", "x": "Trọng số của value loss trong tổng loss: loss = pg_loss + c1·v_loss − c2·entropy . Điều khiển Actor và critic dùng chung thân CNN, nên c1 quyết định gradient của critic \"lấn\" bao nhiêu so với gradient của policy trên các lớp chung. Tăng Critic được ưu tiên, ước lượng giá trị tốt hơn nhưng có thể kéo biểu diễn chung lệch khỏi nhu cầu của policy. Giảm Critic học chậm, advantage nhiễu hơn. Khi nào chỉnh Hiếm. Xem v_loss trong log: nếu nó rất lớn và không giảm thì critic đang gặp khó."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "c2 float mặc định 0.01", "a": "c2", "x": "Trọng số của entropy bonus. Entropy càng cao thì policy càng ngẫu nhiên; phần thưởng này chống việc policy \"chốt\" quá sớm. Điều khiển Mức khám phá. Entropy tối đa là ln 9 ≈ 2.197 (đều trên 9 action). Tăng Khám phá nhiều hơn, tránh kẹt vào chiến thuật kém, nhưng quá lớn thì policy mãi ngẫu nhiên, entropy gần 2.197 không giảm. Giảm Hội tụ nhanh về policy gần tất định; nguy cơ chốt sớm: entropy sụt nhanh trong khi điểm không tăng. Khi nào chỉnh Khi quan sát entropy giảm quá nhanh (tăng c2 ) hoặc không chịu giảm (giảm c2 ). Ví dụ --set c2=0.02 ."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "Tái lập, ghi log, lưu", "a": "infra", "x": ""}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "seed int mặc định 0", "a": "seed", "x": "Seed cho random , numpy , torch và cho các env (env thứ k dùng seed + k ). Điều khiển Khởi tạo trọng số mạng và trạng thái xuất phát của các ván. Lưu ý Cùng seed không đảm bảo cùng kết quả từng chi tiết (xem Seed của từng env ). Dùng nhiều seed để đo độ nhiễu. CLI Dùng --seed (mặc định 0). --set seed=... sẽ bị --seed đè."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "log_every int mặc định 50", "a": "log_every", "x": "In một dòng log mỗi bấy nhiêu update (không phải bước env). Update cuối luôn được in. Lưu ý Chỉ ảnh hưởng việc in ra màn hình . Chỉ số trong log (dùng để vẽ) được ghi mỗi update bất kể giá trị này. Khi nào chỉnh Run ngắn thì đặt nhỏ (ví dụ 5) để thấy log; mặc định 50 update ≈ 102,400 bước."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "save_every int mặc định 200", "a": "save_every", "x": "Lưu checkpoint .pt mỗi bấy nhiêu update (khi có save_path ). Mặc định 200 update ≈ 409,600 bước. Khi nào chỉnh Run dài: đặt nhỏ để mất ít khi máy treo. Chỉ lưu .pt ; _episodes.npy và _log.npy chỉ ghi khi train kết thúc."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "reward_fn Callable mặc định log_reward", "a": "reward_fn", "x": "Hàm nhận mảng reward thật của một nhóm env (độ dài n_envs / 2 ) và trả về mảng reward dùng để học. Mặc định log1p(r / 10) . Điều khiển Chỉ reward học. Điểm báo cáo, số viên năng lượng và số ma vẫn tính từ reward thật. Lưu ý Không đặt được từ CLI ( --set reward_fn=... bị từ chối). Dùng Python. Hàm là hàm thuần, không giữ trạng thái; xem Reward shaping để biết cách làm khi cần trạng thái."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "death_penalty float mặc định 0.0", "a": "death_penalty", "x": "Số điểm trừ khỏi reward học ở bước agent vừa mất một mạng: reward_học = reward_fn(reward) - death_penalty * died . Mặc định 0 là không phạt. Điều khiển Chỉ reward học (cùng thang với reward_fn : chấm nhỏ ≈ 0.69, viên năng lượng ≈ 1.79). Điểm báo cáo, số viên năng lượng và số ma vẫn tính từ reward thật. Khi nào chỉnh Khi agent hay lao vào ma. Giá trị thử: 1 đến 3. Phạt quá lớn khiến agent né ma quá mức và đứng yên."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "step_penalty float mặc định 0.0", "a": "step_penalty", "x": "Số điểm trừ khỏi reward học ở mỗi bước env: reward_học = reward_fn(reward) - step_penalty - death_penalty * died . Mặc định 0 là không phạt. Điều khiển Chỉ reward học, giống death_penalty . Dùng để ép agent không đứng yên hoặc lang thang. Lưu ý Đừng đặt cùng lúc với một reward_fn đã tự trừ phạt mỗi bước, vì sẽ bị phạt hai lần."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "penalty_schedule Callable | None mặc định None", "a": "penalty_schedule", "x": "Hàm tiến_độ -> (death_penalty, step_penalty) , gọi lại mỗi update với tiến_độ = update / tổng update trong [0, 1]. None thì dùng hai hằng số death_penalty và step_penalty . Dựng nhanh piecewise_penalty([(tiến_độ, death_penalty, step_penalty), ...]) nội suy tuyến tính giữa các mốc, ngoài khoảng mốc thì giữ giá trị mốc đầu / cuối. Ví dụ piecewise_penalty([(0, 2.5, 0.0), (0.3, 2.5, 0.0), (0.6, 20, 0.1)]) giữ 2.5 / 0 tới 30% đầu rồi tăng dần lên 20 / 0.1 ở 60%. Ghi log Giá trị đang dùng được ghi vào log[\"death_penalty\"] và log[\"step_penalty\"] , và hiện trong dòng in mỗi log_every update."}, {"p": "reference/ppo-config.html", "t": "PPOConfig", "h": "rgb_scale bool mặc định False", "a": "rgb_scale", "x": "False : agent thấy 4 frame xám, quan sát (4, 84, 84) . True : 4 frame RGB gộp kênh thành (12, 84, 84) . Đánh đổi Bộ nhớ rollout và băng thông CPU→GPU tăng khoảng 3 lần; số tham số gần như không đổi (chỉ lớp conv đầu rộng hơn). Đổi lại agent thấy được màu, ví dụ ma chuyển xanh khi ăn viên năng lượng. Tự nhận biết load_model đọc số kênh từ checkpoint, và ppo_policy / dqn_policy báo cho evaluate / watch dựng env cùng loại, nên không cần cấu hình lại khi đánh giá. Chỉ PPO hỗ trợ; DQN vẫn dùng ảnh xám."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "", "a": "", "x": "Khác Thông báo lỗi hay gặp, cách hiểu và cách sửa; cùng những câu hỏi thường gặp về cách thư viện hoạt động. Các lỗi có ghi \"đã tái hiện\" đã được chạy thật để lấy đúng thông báo."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Cài đặt và môi trường", "a": "install", "x": ""}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Máy có GPU nhưng thiết bị là cpu", "a": "cpu-only", "x": "describe_device(get_device()) in cpu | CPU . Torch bạn cài là bản CPU (thường do pip kéo torch tự động đè lên). Cài lại bản CUDA rồi cài lại pacman_rl với --no-deps : pip install torch==2.3.1 --index-url https://download.pytorch.org/whl/cu121 pip install -e pacman_rl --no-deps"}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "ModuleNotFoundError: No module named 'pacman_rl'", "a": "no-module", "x": "Thư viện chưa được cài vào môi trường đang dùng, hoặc bạn đang chạy bằng Python của môi trường khác. Kiểm tra bằng python -c \"import sys; print(sys.executable)\" , bật đúng môi trường rồi pip install -e pacman_rl ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "NamespaceNotFound: Namespace ALE not found", "a": "ale-namespace", "x": "(Đã tái hiện.) Xảy ra khi bạn tự gọi gym.make(\"ALE/MsPacman-v5\") mà chưa import ale_py . make_env() của thư viện đã import sẵn, nên dùng nó thay vì gym.make trực tiếp, hoặc thêm import ale_py ở đầu."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Lỗi liên quan đến numpy khi import", "a": "numpy2", "x": "Dự án ghim numpy<2 để khớp gymnasium 0.29 và torch 2.3. Nếu một gói khác nâng numpy lên 2.x, đưa về: pip install \"numpy<2\" ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Windows", "a": "windows", "x": ""}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Script chạy lại chính nó, hoặc báo \"bootstrapping phase\"", "a": "windows-main", "x": "Env song song dùng multiprocessing kiểu spawn : mỗi process con import lại file chính. Lệnh train_* đặt ngoài khối bảo vệ sẽ được chạy lại trong process con, gây lỗi hoặc vòng lặp tạo process. Đặt vào hàm và bảo vệ: def main(): ... # gọi train_ppo / train_dqn ở đây if __name__ == \"__main__\": main() Dòng lệnh python -m pacman_rl ... đã xử lý sẵn ( __main__.py ), và notebook thường không cần."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "UnicodeEncodeError: 'charmap' codec can't encode character", "a": "unicode", "x": "(Đã tái hiện.) Log của hàm train có tiếng Việt, mà console Windows mặc định là cp1252. Gọi train_ppo trong script riêng sẽ dừng ngay ở dòng print đầu tiên. Cách sửa: python -X utf8 train_script.py # hoặc đặt biến môi trường cho cả phiên: set PYTHONUTF8=1 (PowerShell: $env:PYTHONUTF8 = \"1\") Dòng lệnh python -m pacman_rl tự chuyển stdout sang UTF-8 nên không bị."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Dòng lệnh", "a": "cli", "x": ""}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Không có tham số 'xxx'. Hợp lệ: ...", "a": "bad-param", "x": "(Đã tái hiện.) Tên sau --set không có trong config của thuật toán đang train. Thông báo liệt kê các tên hợp lệ. Nhớ rằng tham số của PPO và DQN khác nhau ( n_steps , clip_eps chỉ có ở PPO; buffer_size , eps_* chỉ có ở DQN)."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "ValueError: could not convert string to float với --set", "a": "bool-set", "x": "(Đã tái hiện.) Trường kiểu bool được đọc qua float , nên dùng 1 hoặc 0 , không dùng true / false hay maybe ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "AssertionError ngay khi bắt đầu train", "a": "odd-envs", "x": "(Đã tái hiện.) n_envs lẻ. PipelinedEnvs chia env thành 2 nhóm nên n_envs phải chẵn. Thông báo lỗi không có chữ, nhưng nguyên nhân là điều kiện n_envs % n_groups == 0 ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Error(s) in loading state_dict for QNetwork: Missing key(s) ... \"head.weight\"", "a": "wrong-algo", "x": "(Đã tái hiện.) Bạn nạp một run PPO bằng algo=\"dqn\" (hoặc ngược lại). algo quyết định lớp mạng được dựng, và trọng số PPO có khóa actor.* / critic.* thay vì head.* . Dùng đúng algo của run: load_run(dir, name, \"ppo\") cho run PPO."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Trong lúc train", "a": "training", "x": ""}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Chạy chậm (steps/s thấp)", "a": "slow", "x": "Thiết bị là cpu : xem trên . --render đang bật: chạy tuần tự trong một process, rất chậm. Tắt đi, dùng --watch-every nếu muốn xem. n_envs nhiều hơn số nhân CPU: giảm xuống (và tăng n_steps cho PPO để giữ batch). RAM gần đầy (nhất là DQN): đóng ứng dụng khác, giảm buffer_size . Vài chục giây đầu chậm là bình thường (khởi động process con, khởi tạo CUDA)."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Hết RAM khi train DQN", "a": "oom-ram", "x": "Replay buffer tốn khoảng buffer_size × 7,080 byte (1.4 GB cho 200,000) cộng RAM của 16 process con. Giảm buffer_size (ví dụ --set buffer_size=100000 ) hoặc n_envs ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "CUDA out of memory", "a": "oom-gpu", "x": "Minibatch của PPO quá lớn so với GPU: tăng n_minibatches (minibatch = batch / n_minibatches ) hoặc giảm n_envs × n_steps . Với DQN, giảm batch_size ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "avg score(20) là nan", "a": "nan-score", "x": "Chưa có ván nào (đủ 3 mạng) kết thúc, nên chưa có điểm để lấy trung bình. Bình thường ở những update đầu."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "log rỗng sau run ngắn (DQN)", "a": "empty-log", "x": "DQN chỉ ghi log mỗi log_every bước env (mặc định 100,000). Run ngắn hơn thế sẽ không có điểm nào. Đặt --set log_every=1000 (hoặc nhỏ hơn total_steps ). PPO không bị vì nó ghi mỗi update."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "loss, q_mean là nan ở đầu run DQN", "a": "loss-nan", "x": "Chưa học lần nào vì còn trong learning_starts bước đầu. Không phải lỗi."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Process Python còn sót sau khi dừng đột ngột", "a": "stray", "x": "Đóng terminal hay kill process cha giữa lúc train có thể để lại các process env con. Nếu máy bỗng chậm hoặc RAM không giải phóng, mở Task Manager (hoặc Get-Process python ) và kết thúc các process Python thừa. Dùng Ctrl+C thay vì đóng cửa sổ để thư viện tự dọn."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Kết quả và biểu đồ", "a": "results", "x": ""}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Biểu đồ \"ma trên viên năng lượng\" trống hoặc là một đường thẳng", "a": "third-plot", "x": "Nó chia theo khoảng 100,000 bước; run ngắn hơn không có đủ khoảng. Xem ba biểu đồ mặc định ; với run ngắn dùng plot_events(runs, bin_size=10_000) ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "play hoặc watch không mở được cửa sổ", "a": "no-display", "x": "Các lệnh này cần màn hình ( render_mode=\"human\" ). Trên máy từ xa không có màn hình, dùng eval (không mở cửa sổ) thay thế."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Cùng --seed nhưng hai lần train ra kết quả khác nhau", "a": "same-seed", "x": "Đúng như dự kiến. Seed chỉ cố định phần khởi tạo; thứ tự các process env trả kết quả, tính không xác định của GPU và việc lấy mẫu action làm hai lần chạy lệch dần. Dùng nhiều seed để đo độ nhiễu. Xem Seed của từng env ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Điểm eval khác điểm khi train", "a": "eval-differs", "x": "Có thể do: eval chạy trọn ván 3 mạng không qua EpisodicLife ; PPO lấy mẫu vs --greedy ; DQN còn eps ; số ván ít nên nhiễu. Xem Đánh giá ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Câu hỏi thường gặp", "a": "faq", "x": ""}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "16 env có nghĩa là 16 policy không?", "a": "faq-policies", "x": "Không. Chỉ có một mạng neural. 16 env chỉ là nơi thu dữ liệu song song. Xem Env song song và pipeline ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "\"Bước\" khác \"frame\" thế nào?", "a": "faq-steps", "x": "Một bước là một action, tương ứng 4 frame (frame-skip 4). 2 triệu bước là 8 triệu frame. Các bài báo Atari thường báo theo frame."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Có bắt buộc phải có GPU không?", "a": "faq-gpu", "x": "Không, nhưng không có GPU thì chậm đi nhiều và nên giảm total_steps khi thử. Phần mô phỏng emulator chạy trên CPU ở mọi trường hợp."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Nên chọn PPO hay DQN?", "a": "faq-which", "x": "Mặc định của dự án cho PPO 2 triệu bước và DQN 10 triệu bước; PPO chạy nhanh hơn theo thời gian thực trong các phép đo ở thời gian dự kiến . Cái nào cho điểm cao hơn trên Ms. Pacman phụ thuộc cấu hình và ngân sách, và chỉ nên kết luận sau khi chạy nhiều seed."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Có chạy trên Linux/macOS/Colab không?", "a": "faq-linux", "x": "Mã không dùng API riêng của Windows nên về nguyên tắc chạy được, nhưng dự án chỉ được thử trên Windows. Nếu bạn thử trên nền tảng khác, hãy kiểm tra các điểm: phiên bản ale-py , và cách multiprocessing bắt đầu process (trên Linux dùng fork, có thể khác về tiêu thụ RAM)."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Tôi có thể train tiếp một run đã dừng không?", "a": "faq-resume", "x": "Một phần: train_*(cfg, model=...) nạp lại trọng số, còn optimizer, lịch lr, epsilon và replay buffer bắt đầu lại. Xem Train tiếp từ model có sẵn để biết hệ quả và cách giảm nhẹ."}, {"p": "troubleshooting.html", "t": "Xử lý sự cố và FAQ", "h": "Làm sao biết một run đã dùng siêu tham số nào?", "a": "faq-config", "x": "Thư viện không lưu config. CLI in config ở dòng đầu; hãy ghi lại ( | tee ) và đặt --name mô tả cấu hình."}];
